"use client";

import { useEffect, useState } from "react";
import {
  Plus,
  Search,
  Filter,
  MoreVertical,
  Edit2,
  Trash2,
  Copy,
  Bike,
  Save,
  Loader,
  Upload,
  PlusCircle,
  X,
} from "lucide-react";
import Image from "next/image";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { toast } from "sonner";
import { formatPrice } from "@/lib/utils";
import { BIKE_CATEGORIES } from "@/config/constants";
import { adminAPI, Bike as BikeType } from "@/lib/admin-api";

interface Brand {
  id: number;
  name: string;
  logo_url?: string;
}

// Default structure for a variant
const defaultVariant = () => ({
  variant_name: "Standard",
  variant_key: "std",
  price: 0,
  is_default: true,
  braking_system: "",
  rear_brake_type: "",
  tire_type: "Tubeless",
  headlight_type: "",
  kerb_weight: "",
  seat_type: "",
  instrument_console: "",
  mileage_company: "",
  mileage_user: "",
  topspeed_company: "",
  topspeed_user: "",
  color_options: [] as string[],
  mobile_connectivity: false,
  gps_navigation: false,
  riding_modes: false,
  slipper_clutch: false,
  traction_control: false,
  quick_shifter: false,
});

export default function AdminBikesPage() {
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [bikes, setBikes] = useState<BikeType[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string>("");
  const [submitting, setSubmitting] = useState(false);
  const [deletingId, setDeletingId] = useState<number | null>(null);
  const [brands, setBrands] = useState<Brand[]>([]);
  const [variants, setVariants] = useState<ReturnType<typeof defaultVariant>[]>([defaultVariant()]);

  const [newBike, setNewBike] = useState({
    name: "",
    brand: "",
    category: "commuter",
    price: 0,
    description: "",
    engine_capacity: 0,
    engine_type: "petrol",
    gears: 5,
    clutch_type: "wet",
    curb_weight: 0,
    fuel_capacity: 0,
    seat_height: 0,
    tyre_type: "tubeless",
    is_available: true,
    primary_image: "",
    image1: "",
    image2: "",
    image3: "",
    image4: "",
    image5: "",
    detailed_specs: {
      engine_type: "",
      displacement: "",
      max_power: "",
      max_torque: "",
      bore_stroke: "",
      compression_ratio: "",
      fuel_system: "",
      starting: "",
      cooling_system: "",
      valve_train: "",
      emission_standard: "",
      acceleration_0_60: "",
      acceleration_0_100: "",
      top_speed: "",
      mileage_city: "",
      mileage_highway: "",
      fuel_type: "petrol",
      fuel_tank_capacity: "",
      reserve_fuel: "",
      range_per_tank: "",
      clutch: "",
      gearbox: "",
      gear_pattern: "",
      final_drive: "",
      brakes_front: "",
      brakes_rear: "",
      braking_system: "",
      length: "",
      width: "",
      height: "",
      wheelbase: "",
      ground_clearance: "",
      seat_height: "",
      frame_type: "",
      suspension_front: "",
      suspension_rear: "",
      kerb_weight: "",
      dry_weight: "",
      payload_capacity: "",
      tyres_front: "",
      tyres_rear: "",
      tyres_type: "tubeless",
      wheels_front: "",
      wheels_rear: "",
      gear_shift_pattern: "",
      spark_plugs: 1,
      cooling_type: "",
      usb_charging: false,
      side_stand_cut_off: false,
      projector_headlight: false,
      drls: false,
      gear_indicator: false,
      distance_to_empty: false,
      avg_fuel_consumption: false,
    } as any,
  });

  useEffect(() => {
    loadBikes();
    loadBrands();
  }, []);

  const loadBrands = async () => {
    try {
      const data = await adminAPI.getAllBrands();
      setBrands(data || []);
    } catch {
      console.error("Failed to load brands");
    }
  };

  const loadBikes = async () => {
    try {
      setLoading(true);
      const response = await adminAPI.getAllBikes({
        limit: 100,
        offset: 0,
      });
      setBikes(response?.results || []);
    } catch {
      toast.error("Failed to load bikes");
    } finally {
      setLoading(false);
    }
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddBike = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      setSubmitting(true);

      // Build FormData — same pattern as the News module for reliable Cloudinary uploads
      const formData = new FormData();
      formData.append("name", newBike.name);
      formData.append("brand", String(Number(newBike.brand)));
      formData.append("category", newBike.category);
      formData.append("price", String(Number(newBike.price)));
      formData.append("engine_capacity", String(Number(newBike.engine_capacity)));
      formData.append("engine_type", newBike.engine_type || "");
      formData.append("gears", String(newBike.gears || 5));
      formData.append("clutch_type", newBike.clutch_type || "");
      formData.append("curb_weight", String(newBike.curb_weight || 0));
      formData.append("fuel_capacity", String(newBike.fuel_capacity || 0));
      formData.append("seat_height", String(newBike.seat_height || 0));
      formData.append("tyre_type", newBike.tyre_type || "Tubeless");
      formData.append("is_available", String(newBike.is_available));
      if (newBike.description) formData.append("description", newBike.description);

      // Include image files if selected
      if (imageFile) {
        formData.append("primary_image", imageFile);
      } else if (newBike.primary_image) {
        formData.append("primary_image", newBike.primary_image);
      }
      ["image1", "image2", "image3", "image4", "image5"].forEach((key) => {
        const val = (newBike as any)[key];
        if (val) formData.append(key, val);
      });

      // JSON-encode detailed_specs
      formData.append("detailed_specs", JSON.stringify(newBike.detailed_specs));

      // JSON-encode variants
      formData.append("variants_data", JSON.stringify(variants.map((v, i) => ({
        ...v,
        is_default: i === 0,
        price: Number(v.price),
      }))));

      if (editingId) {
        await adminAPI.updateBike(editingId, formData as any);
        toast.success("Bike updated successfully");
      } else {
        await adminAPI.createBike(formData as any);
        toast.success("New bike model added successfully");
      }

      setIsAddDialogOpen(false);
      resetForm();
      await loadBikes();
    } catch (error: any) {
      console.error("Failed to save bike:", error);
      toast.error(error?.message || (editingId ? "Failed to update bike" : "Failed to add bike"));
    } finally {
      setSubmitting(false);
    }
  };

  const resetForm = () => {
    setNewBike({
      name: "",
      brand: "",
      category: "commuter",
      price: 0,
      description: "",
      engine_capacity: 0,
      engine_type: "petrol",
      gears: 5,
      clutch_type: "wet",
      curb_weight: 0,
      fuel_capacity: 0,
      seat_height: 0,
      tyre_type: "tubeless",
      is_available: true,
      primary_image: "",
      image1: "",
      image2: "",
      image3: "",
      image4: "",
      image5: "",
      detailed_specs: {} as any,
    });
    setVariants([defaultVariant()]);
    setImageFile(null);
    setImagePreview("");
    setEditingId(null);
  };

  const handleEdit = (bike: BikeType & { variants?: any[] }) => {
    setNewBike({
      name: bike.name,
      brand: (typeof bike.brand === 'object' ? (bike.brand as { id: number }).id.toString() : bike.brand.toString()),
      category: bike.category,
      price: bike.price,
      description: bike.description || "",
      engine_capacity: bike.engine_capacity || 0,
      engine_type: bike.engine_type || "petrol",
      gears: bike.gears || 5,
      clutch_type: bike.clutch_type || "wet",
      curb_weight: bike.curb_weight || 0,
      fuel_capacity: bike.fuel_capacity || 0,
      seat_height: bike.seat_height || 0,
      tyre_type: bike.tyre_type || "tubeless",
      is_available: bike.is_available ?? true,
      primary_image: bike.primary_image || "",
      image1: bike.image1 || "",
      image2: bike.image2 || "",
      image3: bike.image3 || "",
      image4: bike.image4 || "",
      image5: bike.image5 || "",
      detailed_specs: bike.detailed_specs || {} as any,
    });
    // Load existing variants
    if (bike.variants && bike.variants.length > 0) {
      setVariants(bike.variants.map((v: any) => ({
        variant_name: v.variant_name || "Standard",
        variant_key: v.variant_key || "std",
        price: Number(v.price) || 0,
        is_default: v.is_default ?? false,
        braking_system: v.braking_system || "",
        rear_brake_type: v.rear_brake_type || "",
        tire_type: v.tire_type || "Tubeless",
        headlight_type: v.headlight_type || "",
        kerb_weight: v.kerb_weight || "",
        seat_type: v.seat_type || "",
        instrument_console: v.instrument_console || "",
        mileage_company: v.mileage_company || "",
        mileage_user: v.mileage_user || "",
        topspeed_company: v.topspeed_company || "",
        topspeed_user: v.topspeed_user || "",
        color_options: v.color_options || [],
        mobile_connectivity: !!v.mobile_connectivity,
        gps_navigation: !!v.gps_navigation,
        riding_modes: !!v.riding_modes,
        slipper_clutch: !!v.slipper_clutch,
        traction_control: !!v.traction_control,
        quick_shifter: !!v.quick_shifter,
      })));
    } else {
      setVariants([defaultVariant()]);
    }
    setImagePreview(bike.primary_image || "");
    setEditingId(bike.id);
    setIsAddDialogOpen(true);
  };

  const handleDelete = async (id: number) => {
    if (!confirm("Are you sure you want to delete this bike model?")) return;

    try {
      setDeletingId(id);
      await adminAPI.deleteBike(id);
      toast.success("Bike model deleted successfully");
      await loadBikes();
    } catch (error) {
      console.error("Failed to delete bike:", error);
      toast.error("Failed to delete bike");
    } finally {
      setDeletingId(null);
    }
  };

  const handleDuplicate = async (bike: BikeType) => {
    try {
      await adminAPI.duplicateBike(bike.id);
      toast.success("Bike model duplicated as draft");
      await loadBikes();
    } catch (error) {
      console.error("Failed to duplicate bike:", error);
      toast.error("Failed to duplicate bike");
    }
  };

  const filteredBikes = bikes.filter((bike) => {
    const bikeBrand = (typeof bike.brand === 'object' ? (bike.brand as { name: string }).name : (brands.find(b => b.id.toString() === bike.brand.toString())?.name || ""));
    const matchesSearch =
      bike.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      bikeBrand.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory =
      categoryFilter === "all" || bike.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Official Bikes</h1>
          <p className="text-muted-foreground">
            Manage the database of official motorcycle models available in
            Bangladesh.
          </p>
        </div>

        <Dialog
          open={isAddDialogOpen}
          onOpenChange={(open) => {
            setIsAddDialogOpen(open);
            if (!open) resetForm();
          }}
        >
          <DialogTrigger asChild>
            <Button className="shrink-0">
              <Plus className="mr-2 h-4 w-4" /> Add New Bike
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
            <form onSubmit={handleAddBike}>
              <DialogHeader>
                <DialogTitle>
                  {editingId ? "Edit Bike Model" : "Add Official Bike Model"}
                </DialogTitle>
                <DialogDescription>
                  {editingId
                    ? "Update bike specifications."
                    : "Create a new entry in the official bike database."}
                </DialogDescription>
              </DialogHeader>

              <Tabs defaultValue="basic" className="mt-6">
                <TabsList className="grid w-full grid-cols-3 md:grid-cols-7 h-auto">
                  <TabsTrigger value="basic">Basic</TabsTrigger>
                  <TabsTrigger value="engine">Engine</TabsTrigger>
                  <TabsTrigger value="chassis">Chassis</TabsTrigger>
                  <TabsTrigger value="dims">Dimensions</TabsTrigger>
                  <TabsTrigger value="features">Features</TabsTrigger>
                  <TabsTrigger value="variants">Variants</TabsTrigger>
                  <TabsTrigger value="image">Images</TabsTrigger>
                </TabsList>

                <TabsContent value="basic" className="space-y-4 pt-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="name">Bike Name *</Label>
                      <Input
                        id="name"
                        placeholder="e.g. Yamaha R15 V4"
                        required
                        value={newBike.name}
                        onChange={(e) =>
                          setNewBike({ ...newBike, name: e.target.value })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="brand">Brand *</Label>
                      <Select
                        value={newBike.brand}
                        onValueChange={(v) =>
                          setNewBike({ ...newBike, brand: v })
                        }
                        required
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="Select Brand" />
                        </SelectTrigger>
                        <SelectContent>
                          {brands.map((brand) => (
                            <SelectItem key={brand.id} value={brand.id.toString()}>
                              {brand.name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="top_speed">Top Speed</Label>
                      <Input
                        id="top_speed"
                        placeholder="e.g. 150 kmph"
                        value={newBike.detailed_specs?.top_speed || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, top_speed: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="mileage_city">Mileage (City)</Label>
                      <Input
                        id="mileage_city"
                        placeholder="e.g. 40 kmpl"
                        value={newBike.detailed_specs?.mileage_city || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, mileage_city: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="mileage_highway">Mileage (Highway)</Label>
                      <Input
                        id="mileage_highway"
                        placeholder="e.g. 45 kmpl"
                        value={newBike.detailed_specs?.mileage_highway || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, mileage_highway: e.target.value } 
                          })
                        }
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="category">Category *</Label>
                      <Select
                        value={newBike.category}
                        onValueChange={(v) =>
                          setNewBike({ ...newBike, category: v })
                        }
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {BIKE_CATEGORIES.map((cat) => (
                            <SelectItem key={cat.value} value={cat.value}>
                              {cat.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="price">Base Price (BDT) *</Label>
                      <Input
                        id="price"
                        type="number"
                        placeholder="0"
                        required
                        value={newBike.price || ""}
                        onChange={(e) =>
                          setNewBike({
                            ...newBike,
                            price: Number(e.target.value),
                          })
                        }
                      />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="description">Description</Label>
                    <Textarea
                      id="description"
                      placeholder="Write a brief overview for the bike's landing page..."
                      rows={4}
                      value={newBike.description}
                      onChange={(e) =>
                        setNewBike({ ...newBike, description: e.target.value })
                      }
                    />
                  </div>
                </TabsContent>

                <TabsContent value="engine" className="space-y-4 pt-4">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="displacement">Displacement (CC)</Label>
                      <Input
                        id="displacement"
                        placeholder="e.g. 155 cc"
                        value={newBike.detailed_specs?.displacement || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, displacement: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                    <Label htmlFor="max_power">Max Power</Label>
                    <Input
                      id="max_power"
                      placeholder="e.g. 18.4 HP @ 10000 rpm"
                      value={newBike.detailed_specs?.max_power || ""}
                      onChange={(e) =>
                        setNewBike({ 
                          ...newBike, 
                          detailed_specs: { ...newBike.detailed_specs, max_power: e.target.value } 
                        })
                      }
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="max_torque">Max Torque</Label>
                    <Input
                      id="max_torque"
                      placeholder="e.g. 14.2 Nm @ 7500 rpm"
                      value={newBike.detailed_specs?.max_torque || ""}
                      onChange={(e) =>
                        setNewBike({ 
                          ...newBike, 
                          detailed_specs: { ...newBike.detailed_specs, max_torque: e.target.value } 
                        })
                      }
                    />
                  </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="engine_type_detail">Engine Type</Label>
                      <Input
                        id="engine_type_detail"
                        placeholder="e.g. Liquid-cooled, 4-stroke, SOHC"
                        value={newBike.detailed_specs?.engine_type || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, engine_type: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="fuel_system">Fuel System</Label>
                      <Input
                        id="fuel_system"
                        placeholder="e.g. Fuel Injection"
                        value={newBike.detailed_specs?.fuel_system || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, fuel_system: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="cooling">Cooling System</Label>
                      <Input
                        id="cooling"
                        placeholder="e.g. Liquid Cooled"
                        value={newBike.detailed_specs?.cooling_system || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, cooling_system: e.target.value } 
                          })
                        }
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="gears">Gears</Label>
                      <Input
                        id="gears"
                        placeholder="e.g. 6-speed"
                        value={newBike.detailed_specs?.gearbox || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, gearbox: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="clutch">Clutch</Label>
                      <Input
                        id="clutch"
                        placeholder="e.g. Wet Multi-plate"
                        value={newBike.detailed_specs?.clutch || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, clutch: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="starting">Starting</Label>
                      <Input
                        id="starting"
                        placeholder="e.g. Self Start"
                        value={newBike.detailed_specs?.starting || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, starting: e.target.value } 
                          })
                        }
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="cooling_type">Cooling Type</Label>
                      <Input
                        id="cooling_type"
                        placeholder="e.g. Air Cooled"
                        value={newBike.detailed_specs?.cooling_type || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, cooling_type: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="spark_plugs">Spark Plugs</Label>
                      <Input
                        id="spark_plugs"
                        type="number"
                        placeholder="1"
                        value={newBike.detailed_specs?.spark_plugs || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, spark_plugs: Number(e.target.value) } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="gear_pattern">Gear Shift Pattern</Label>
                      <Input
                        id="gear_pattern"
                        placeholder="e.g. 1-N-2-3-4-5"
                        value={newBike.detailed_specs?.gear_shift_pattern || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, gear_shift_pattern: e.target.value } 
                          })
                        }
                      />
                    </div>
                  </div>
                </TabsContent>

                <TabsContent value="chassis" className="space-y-4 pt-4">
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="brakes_front">Front Brake</Label>
                      <Input
                        id="brakes_front"
                        placeholder="e.g. 282mm Disc"
                        value={newBike.detailed_specs?.brakes_front || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, brakes_front: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="brakes_rear">Rear Brake</Label>
                      <Input
                        id="brakes_rear"
                        placeholder="e.g. 220mm Disc"
                        value={newBike.detailed_specs?.brakes_rear || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, brakes_rear: e.target.value } 
                          })
                        }
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="braking_system">Braking System</Label>
                      <Input
                        id="braking_system"
                        placeholder="e.g. Dual Channel ABS"
                        value={newBike.detailed_specs?.braking_system || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, braking_system: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="tyres_front">Front Tyre</Label>
                      <Input
                        id="tyres_front"
                        placeholder="e.g. 100/80-17"
                        value={newBike.detailed_specs?.tyres_front || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, tyres_front: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="tyres_rear">Rear Tyre</Label>
                      <Input
                        id="tyres_rear"
                        placeholder="e.g. 140/70-17"
                        value={newBike.detailed_specs?.tyres_rear || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, tyres_rear: e.target.value } 
                          })
                        }
                      />
                    </div>
                  </div>
                </TabsContent>

                <TabsContent value="features" className="space-y-4 pt-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {[
                      { id: "usb_charging", label: "USB Charging" },
                      { id: "side_stand_cut_off", label: "Side Stand Cut-off" },
                      { id: "projector_headlight", label: "Projector Headlight" },
                      { id: "drls", label: "DRLs" },
                      { id: "gear_indicator", label: "Gear Indicator" },
                      { id: "distance_to_empty", label: "Distance to Empty" },
                      { id: "avg_fuel_consumption", label: "Avg Fuel Consumption" },
                    ].map((feature) => (
                      <div key={feature.id} className="flex items-center space-x-2 border p-3 rounded-lg">
                        <Checkbox 
                          id={feature.id} 
                          checked={newBike.detailed_specs?.[feature.id] || false}
                          onCheckedChange={(checked) => 
                            setNewBike({
                              ...newBike,
                              detailed_specs: {
                                ...newBike.detailed_specs,
                                [feature.id]: !!checked
                              }
                            })
                          }
                        />
                        <Label htmlFor={feature.id} className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
                          {feature.label}
                        </Label>
                      </div>
                    ))}
                  </div>
                </TabsContent>

                <TabsContent value="dims" className="space-y-4 pt-4">
                   <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="kerb_weight">Kerb Weight</Label>
                      <Input
                        id="kerb_weight"
                        placeholder="e.g. 142 kg"
                        value={newBike.detailed_specs?.kerb_weight || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, kerb_weight: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="fuel_capacity_spec">Fuel capacity</Label>
                      <Input
                        id="fuel_capacity_spec"
                        placeholder="e.g. 11 L"
                        value={newBike.detailed_specs?.fuel_tank_capacity || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, fuel_tank_capacity: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="seat_height_spec">Seat Height</Label>
                      <Input
                        id="seat_height_spec"
                        placeholder="e.g. 815 mm"
                        value={newBike.detailed_specs?.seat_height || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, seat_height: e.target.value } 
                          })
                        }
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="ground_clearance">Ground Clearance</Label>
                      <Input
                        id="ground_clearance"
                        placeholder="e.g. 170 mm"
                        value={newBike.detailed_specs?.ground_clearance || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, ground_clearance: e.target.value } 
                          })
                        }
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="wheelbase">Wheelbase</Label>
                      <Input
                        id="wheelbase"
                        placeholder="e.g. 1325 mm"
                        value={newBike.detailed_specs?.wheelbase || ""}
                        onChange={(e) =>
                          setNewBike({ 
                            ...newBike, 
                            detailed_specs: { ...newBike.detailed_specs, wheelbase: e.target.value } 
                          })
                        }
                      />
                    </div>
                  </div>
                </TabsContent>

                <TabsContent value="variants" className="space-y-4 pt-4">
                  <div className="flex items-center justify-between mb-2">
                    <div>
                      <p className="text-sm font-semibold">Variants ({variants.length})</p>
                      <p className="text-xs text-muted-foreground">Each variant can have different specs and pricing.</p>
                    </div>
                    {variants.length < 4 && (
                      <Button type="button" size="sm" variant="outline"
                        onClick={() => setVariants(prev => [...prev, { ...defaultVariant(), variant_name: `Variant ${prev.length + 1}`, variant_key: `v${prev.length + 1}`, is_default: false }])}
                      >
                        <PlusCircle className="h-4 w-4 mr-1" /> Add Variant
                      </Button>
                    )}
                  </div>

                  {variants.map((variant, idx) => (
                    <div key={idx} className="border rounded-lg p-4 space-y-4">
                      <div className="flex items-center justify-between">
                        <h4 className="font-semibold text-sm">
                          {idx === 0 ? "Default Variant" : `Variant ${idx + 1}`}
                          {idx === 0 && <span className="ml-2 text-xs text-primary bg-primary/10 px-2 py-0.5 rounded-full">Default</span>}
                        </h4>
                        {idx > 0 && (
                          <Button type="button" size="sm" variant="ghost" className="text-destructive h-7 w-7 p-0"
                            onClick={() => setVariants(prev => prev.filter((_, i) => i !== idx))}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        )}
                      </div>
                      {/* Identity */}
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                        <div className="space-y-1">
                          <Label className="text-xs">Variant Name *</Label>
                          <Input value={variant.variant_name}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, variant_name: e.target.value} : v))}
                            placeholder="e.g. ABS" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Variant Key</Label>
                          <Input value={variant.variant_key}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, variant_key: e.target.value} : v))}
                            placeholder="e.g. abs" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Price (BDT) *</Label>
                          <Input type="number" value={variant.price}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, price: Number(e.target.value)} : v))}
                            placeholder="0" />
                        </div>
                      </div>
                      {/* Performance */}
                      <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
                        <div className="space-y-1">
                          <Label className="text-xs">Top Speed (Company Claimed)</Label>
                          <Input value={variant.topspeed_company}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, topspeed_company: e.target.value} : v))}
                            placeholder="e.g. 135 kmph" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Top Speed (User Claimed)</Label>
                          <Input value={variant.topspeed_user}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, topspeed_user: e.target.value} : v))}
                            placeholder="e.g. 128 kmph" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Mileage (Company Claimed)</Label>
                          <Input value={variant.mileage_company}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, mileage_company: e.target.value} : v))}
                            placeholder="e.g. 45 kmpl" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Mileage (User Claimed)</Label>
                          <Input value={variant.mileage_user}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, mileage_user: e.target.value} : v))}
                            placeholder="e.g. 40 kmpl" />
                        </div>
                      </div>
                      {/* Brakes & Wheels */}
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                        <div className="space-y-1">
                          <Label className="text-xs">Braking System</Label>
                          <Input value={variant.braking_system}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, braking_system: e.target.value} : v))}
                            placeholder="e.g. Disc / Drum, ABS" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Rear Brake Type</Label>
                          <Input value={variant.rear_brake_type}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, rear_brake_type: e.target.value} : v))}
                            placeholder="e.g. 130mm Drum" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Tyre Type</Label>
                          <Input value={variant.tire_type}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, tire_type: e.target.value} : v))}
                            placeholder="e.g. Tubeless" />
                        </div>
                      </div>
                      {/* Other specs */}
                      <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
                        <div className="space-y-1">
                          <Label className="text-xs">Headlight Type</Label>
                          <Input value={variant.headlight_type}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, headlight_type: e.target.value} : v))}
                            placeholder="e.g. LED Projector" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Kerb Weight</Label>
                          <Input value={variant.kerb_weight}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, kerb_weight: e.target.value} : v))}
                            placeholder="e.g. 140 kg" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Instrument Console</Label>
                          <Input value={variant.instrument_console}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, instrument_console: e.target.value} : v))}
                            placeholder="e.g. TFT Digital" />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Seat Type</Label>
                          <Input value={variant.seat_type}
                            onChange={e => setVariants(prev => prev.map((v, i) => i === idx ? {...v, seat_type: e.target.value} : v))}
                            placeholder="e.g. Split Seat" />
                        </div>
                      </div>
                      {/* Feature flags */}
                      <div>
                        <p className="text-xs font-semibold mb-2 text-muted-foreground uppercase tracking-wider">Features</p>
                        <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                          {[
                            { key: "mobile_connectivity", label: "Mobile Phone Connectivity" },
                            { key: "gps_navigation", label: "GPS & Navigation" },
                            { key: "riding_modes", label: "Riding Modes" },
                            { key: "slipper_clutch", label: "Slipper / Assist Clutch" },
                            { key: "traction_control", label: "Traction Control" },
                            { key: "quick_shifter", label: "Quick Shifter" },
                          ].map(feat => (
                            <div key={feat.key} className="flex items-center gap-2">
                              <Checkbox id={`${feat.key}-${idx}`}
                                checked={!!(variant as any)[feat.key]}
                                onCheckedChange={checked => setVariants(prev => prev.map((v, i) => i === idx ? {...v, [feat.key]: !!checked} : v))}
                              />
                              <Label htmlFor={`${feat.key}-${idx}`} className="text-xs">{feat.label}</Label>
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  ))}
                </TabsContent>

                <TabsContent value="image" className="space-y-4 pt-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {/* Primary Image */}
                    <div className="space-y-2">
                      <Label>Primary Image *</Label>
                      <ImageUploadSlot
                        id="primary_image"
                        preview={imagePreview || newBike.primary_image}
                        onUpload={async (file) => {
                          const res = await adminAPI.uploadImage(file);
                          if (res?.url) {
                            setNewBike(prev => ({ ...prev, primary_image: res.url }));
                            setImagePreview(res.url);
                          }
                        }}
                      />
                    </div>
                    {/* Image 1 */}
                    <div className="space-y-2">
                      <Label>Image 1</Label>
                      <ImageUploadSlot
                        id="image1"
                        preview={newBike.image1}
                        onUpload={async (file) => {
                          const res = await adminAPI.uploadImage(file);
                          if (res?.url) {
                            setNewBike(prev => ({ ...prev, image1: res.url }));
                          }
                        }}
                      />
                    </div>
                    {/* Image 2 */}
                    <div className="space-y-2">
                      <Label>Image 2</Label>
                      <ImageUploadSlot
                        id="image2"
                        preview={newBike.image2}
                        onUpload={async (file) => {
                          const res = await adminAPI.uploadImage(file);
                          if (res?.url) {
                            setNewBike(prev => ({ ...prev, image2: res.url }));
                          }
                        }}
                      />
                    </div>
                    {/* Image 3 */}
                    <div className="space-y-2">
                      <Label>Image 3</Label>
                      <ImageUploadSlot
                        id="image3"
                        preview={newBike.image3}
                        onUpload={async (file) => {
                          const res = await adminAPI.uploadImage(file);
                          if (res?.url) {
                            setNewBike(prev => ({ ...prev, image3: res.url }));
                          }
                        }}
                      />
                    </div>
                    {/* Image 4 */}
                    <div className="space-y-2">
                      <Label>Image 4</Label>
                      <ImageUploadSlot
                        id="image4"
                        preview={newBike.image4}
                        onUpload={async (file) => {
                          const res = await adminAPI.uploadImage(file);
                          if (res?.url) {
                            setNewBike(prev => ({ ...prev, image4: res.url }));
                          }
                        }}
                      />
                    </div>
                    {/* Image 5 */}
                    <div className="space-y-2">
                      <Label>Image 5</Label>
                      <ImageUploadSlot
                        id="image5"
                        preview={newBike.image5}
                        onUpload={async (file) => {
                          const res = await adminAPI.uploadImage(file);
                          if (res?.url) {
                            setNewBike(prev => ({ ...prev, image5: res.url }));
                          }
                        }}
                      />
                    </div>
                  </div>
                </TabsContent>
              </Tabs>

              <DialogFooter className="mt-8">
                <Button
                  variant="outline"
                  type="button"
                  onClick={() => {
                    setIsAddDialogOpen(false);
                    resetForm();
                  }}
                  disabled={submitting}
                >
                  Cancel
                </Button>
                <Button type="submit" disabled={submitting}>
                  {submitting ? (
                    <>
                      <Loader className="mr-2 h-4 w-4 animate-spin" /> Saving...
                    </>
                  ) : (
                    <>
                      <Save className="mr-2 h-4 w-4" />{" "}
                      {editingId ? "Update" : "Create"} Bike
                    </>
                  )}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader className="pb-3">
          <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
            <div className="relative w-full md:w-96">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search by name or brand..."
                className="pl-10"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <div className="flex items-center gap-2 w-full md:w-auto">
              <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                <SelectTrigger className="w-full md:w-45">
                  <SelectValue placeholder="All Categories" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Categories</SelectItem>
                  {BIKE_CATEGORIES.map((cat) => (
                    <SelectItem key={cat.value} value={cat.value}>
                      {cat.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button variant="outline" size="icon">
                <Filter className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex justify-center items-center py-12">
              <Loader className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : (
            <div className="rounded-md border overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-20">Image</TableHead>
                    <TableHead>Bike Model</TableHead>
                    <TableHead>Category</TableHead>
                    <TableHead>Base Price</TableHead>
                    <TableHead>Engine</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredBikes.map((bike) => (
                    <TableRow key={bike.id}>
                      <TableCell>
                        <div className="h-12 w-16 rounded overflow-hidden bg-muted relative">
                          {bike.primary_image ? (
                            <Image
                              src={bike.primary_image}
                              alt={bike.name}
                              fill
                              className="object-cover"
                              unoptimized
                            />
                          ) : (
                            <div className="h-full w-full flex items-center justify-center">
                              <Bike className="h-6 w-6 text-muted-foreground" />
                            </div>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="font-medium">{bike.name}</div>
                        <div className="text-xs text-muted-foreground">
                          {bike.brand_name || (typeof bike.brand === 'object' ? (bike.brand as { name: string }).name : brands.find(b => b.id.toString() === bike.brand.toString())?.name) || 'Unknown Brand'}
                        </div>
                      </TableCell>
                      <TableCell>
                        <Badge variant="outline" className="capitalize">
                          {bike.category}
                        </Badge>
                      </TableCell>
                      <TableCell>{formatPrice(bike.price)}</TableCell>
                      <TableCell className="text-sm">
                        {bike.engine_capacity}cc {bike.engine_type}
                      </TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button
                              variant="ghost"
                              size="icon"
                              disabled={deletingId === bike.id}
                            >
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end" className="w-48">
                            <DropdownMenuLabel>Actions</DropdownMenuLabel>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem onClick={() => handleEdit(bike)}>
                              <Edit2 className="mr-2 h-4 w-4" /> Edit Details
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => handleDuplicate(bike)}
                            >
                              <Copy className="mr-2 h-4 w-4" /> Duplicate
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              className="text-destructive focus:text-destructive"
                              onClick={() => handleDelete(bike.id)}
                            >
                              {deletingId === bike.id ? (
                                <>
                                  <Loader className="mr-2 h-4 w-4 animate-spin" />{" "}
                                  Deleting...
                                </>
                              ) : (
                                <>
                                  <Trash2 className="mr-2 h-4 w-4" /> Delete
                                  Model
                                </>
                              )}
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                  {filteredBikes.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={6} className="h-24 text-center">
                        <div className="flex flex-col items-center justify-center text-muted-foreground">
                          <Bike className="h-8 w-8 mb-2 opacity-20" />
                          <p>
                            {bikes.length === 0
                              ? "No bikes yet. Create the first one!"
                              : "No bikes found matching your filters."}
                          </p>
                        </div>
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

function ImageUploadSlot({ 
  id, 
  preview, 
  onUpload 
}: { 
  id: string, 
  preview?: string, 
  onUpload: (file: File) => Promise<void> 
}) {
  const [uploading, setUploading] = useState(false);

  const handleChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        setUploading(true);
        await onUpload(file);
      } catch (error) {
        console.error("Upload error:", error);
        toast.error("Failed to upload image");
      } finally {
        setUploading(false);
      }
    }
  };

  return (
    <div className="relative aspect-video w-full rounded-lg overflow-hidden bg-muted border-2 border-dashed flex flex-col items-center justify-center cursor-pointer hover:bg-muted/80 transition group">
      {preview ? (
        <div className="relative w-full h-full">
           <Image
            src={preview}
            alt="preview"
            fill
            className="object-cover"
            unoptimized
          />
          <label 
            htmlFor={id} 
            className="absolute inset-x-0 bottom-0 bg-black/60 text-white text-[10px] py-1 text-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer font-medium"
          >
            Change Image
          </label>
          {uploading && (
             <div className="absolute inset-0 bg-black/50 flex items-center justify-center">
               <Loader className="h-6 w-6 text-white animate-spin" />
             </div>
          )}
        </div>
      ) : (
        <label htmlFor={id} className="cursor-pointer flex flex-col items-center gap-2 p-4 text-center w-full h-full justify-center">
          {uploading ? (
            <Loader className="h-8 w-8 text-muted-foreground animate-spin" />
          ) : (
            <>
              <Upload className="h-8 w-8 text-muted-foreground" />
              <span className="text-xs font-medium uppercase tracking-wider text-muted-foreground">Click to upload</span>
            </>
          )}
        </label>
      )}
      <input
        id={id}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={handleChange}
        disabled={uploading}
      />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import Image from "next/image";
import {
  LayoutDashboard,
  Bike,
  Store,
  Newspaper,
  Settings,
  ChevronLeft,
  Menu,
  LogOut,
  Bell,
  User,
  ArrowLeft,
  Bug,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { useAuthStore } from "@/store";
import { Separator } from "@/components/ui/separator";
import { signOut } from "next-auth/react";

const adminNav = [
  { name: "Dashboard", href: "/admin", icon: LayoutDashboard },
  { name: "Official Bikes", href: "/admin/bikes", icon: Bike },
  { name: "Used Bike Ads", href: "/admin/used-bikes", icon: Store },
  { name: "News & Articles", href: "/admin/news", icon: Newspaper },
];

export default function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const router = useRouter();
  const { user, isAuthenticated, isLoading } = useAuthStore();
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isMobile, setIsMobile] = useState(false);

  // Close sidebar by default on mobile
  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 768;
      setIsMobile(mobile);
      if (mobile) {
        setIsSidebarOpen(false);
      } else {
        setIsSidebarOpen(true);
      }
    };

    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  // Protection logic
  useEffect(() => {
    if (isLoading) return;
    // Redirect to login if not authenticated
    if (!isAuthenticated) {
      router.push("/login");
      return;
    }
    // Redirect to home if authenticated but not admin
    if (user && user.role !== "admin") {
      router.push("/");
    }
  }, [user, isAuthenticated, router, isLoading]);

  if (isLoading || !isAuthenticated || !user || user.role !== "admin") {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen space-y-4">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
        <p className="text-muted-foreground font-medium">
          Checking admin access...
        </p>
      </div>
    );
  }

  return (
    <div className="flex h-[calc(100vh-4rem)] bg-muted/30 relative">
      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-30 md:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside
        className={cn(
          "bg-background border-r transition-all duration-300 flex flex-col z-40",
          "fixed md:relative top-16 md:top-0 left-0 bottom-0 h-[calc(100vh-4rem)] md:h-auto",
          isSidebarOpen
            ? "w-64 translate-x-0"
            : "w-0 md:w-20 -translate-x-full md:translate-x-0 overflow-hidden",
        )}
      >
        <div className="p-4 flex items-center justify-between h-14 shrink-0">
          <div className="flex items-center gap-2">
            {isSidebarOpen && (
              <span className="font-bold text-xl">Admin Panel</span>
            )}
          </div>
          <Button
            variant="ghost"
            size="icon"
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className={cn(
              "transition-all",
              !isSidebarOpen && !isMobile && "mx-auto",
            )}
          >
            {isSidebarOpen ? (
              <ChevronLeft className="h-5 w-5" />
            ) : (
              <Menu className="h-5 w-5" />
            )}
          </Button>
        </div>

        <div className="flex-1 overflow-y-auto px-3 py-4">
          <nav className="space-y-1">
            {adminNav.map((item) => {
              const isActive = pathname === item.href;
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  className={cn(
                    "flex items-center gap-3 px-3 py-2 rounded-lg transition-colors group",
                    isActive
                      ? "bg-primary text-primary-foreground"
                      : "text-muted-foreground hover:bg-accent hover:text-accent-foreground",
                    !isSidebarOpen && !isMobile && "md:justify-center md:px-2",
                  )}
                  onClick={() => {
                    if (isMobile) setIsSidebarOpen(false);
                  }}
                >
                  <item.icon
                    className={cn(
                      "h-5 w-5 shrink-0",
                      isActive
                        ? ""
                        : "text-muted-foreground group-hover:text-accent-foreground",
                    )}
                  />
                  {(isSidebarOpen || isMobile) && (
                    <span className="font-medium whitespace-nowrap">
                      {item.name}
                    </span>
                  )}
                </Link>
              );
            })}
          </nav>
        </div>

        <div className="p-4 border-t space-y-2">
          {/* Debug Tools */}
          <Link
            href="/admin/debug"
            className={cn(
              "flex items-center gap-3 px-3 py-2 rounded-lg transition-colors text-muted-foreground hover:bg-accent hover:text-accent-foreground",
              !isSidebarOpen && !isMobile && "md:justify-center md:px-2",
            )}
            onClick={() => {
              if (isMobile) setIsSidebarOpen(false);
            }}
          >
            <Bug className="h-5 w-5 shrink-0" />
            {(isSidebarOpen || isMobile) && (
              <span className="font-medium whitespace-nowrap">Debug Tools</span>
            )}
          </Link>

          {/* Settings Link (Moved from Top Nav) */}
          <Link
            href="/admin/settings"
            className={cn(
              "flex items-center gap-3 px-3 py-2 rounded-lg transition-colors text-muted-foreground hover:bg-accent hover:text-accent-foreground",
              !isSidebarOpen && !isMobile && "md:justify-center md:px-2",
            )}
            onClick={() => {
              if (isMobile) setIsSidebarOpen(false);
            }}
          >
            <Settings className="h-5 w-5 shrink-0" />
            {(isSidebarOpen || isMobile) && (
              <span className="font-medium whitespace-nowrap">Settings</span>
            )}
          </Link>

          <Button
            variant="ghost"
            className={cn(
              "w-full justify-start text-muted-foreground hover:text-destructive hover:bg-destructive/5",
              !isSidebarOpen && !isMobile && "md:px-2 md:justify-center",
            )}
            onClick={() => signOut()}
          >
            <LogOut className="h-5 w-5 shrink-0" />
            {(isSidebarOpen || isMobile) && (
              <span className="ml-3 font-medium whitespace-nowrap">Logout</span>
            )}
          </Button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden w-full">
        {/* Mobile Sub-Header with Toggle */}
        <div className="md:hidden flex items-center p-4 bg-background border-b h-14 shrink-0">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => setIsSidebarOpen(true)}
            className="mr-2"
          >
            <Menu className="h-5 w-5" />
          </Button>
          <h2 className="font-semibold truncate">
            {adminNav.find((item) => item.href === pathname)?.name ||
              "Dashboard"}
          </h2>
        </div>

        {/* Page Content */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-muted/20">
          <div className="max-w-7xl mx-auto space-y-6 md:space-y-8">
            {children}
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import {
  Plus,
  Search,
  Filter,
  MoreVertical,
  Edit2,
  Trash2,
  Eye,
  Newspaper,
  Calendar,
  User as UserIcon,
  ArrowUpRight,
  Save,
  Image as ImageIcon,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "sonner";
import { useNews } from "@/hooks/use-news";
import { adminAPI } from "@/lib/admin-api";
import { getSafeImageUrl } from "@/lib/utils";

interface Tag {
  id: number;
  name: string;
}

interface Article {
  id: string | number;
  title: string;
  slug?: string;
  category: string;
  excerpt?: string;
  content: string;
  author?: {
    id: string | number;
    username: string;
    first_name?: string;
    last_name?: string;
  };
  tags?: string[] | Tag[];
  featured_image?: string;
  created_at?: string | Date;
  published_at?: string | Date;
  views?: number;
  is_published?: boolean;
}

const CATEGORIES = [
  { label: "Launch", value: "launch" },
  { label: "Review", value: "review" },
  { label: "Feature", value: "feature" },
  { label: "Tips", value: "tips" },
  { label: "News", value: "news" },
];

export default function AdminNewsPage() {
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("all");

  const { data: articlesData, refetch } = useNews(
    categoryFilter !== "all" ? { category: categoryFilter } : undefined,
  );

  // Handle data structure from useNews hook ({ articles, meta })
  const articles = articlesData?.articles || [];

  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [currentImagePreview, setCurrentImagePreview] = useState<string | null>(
    null,
  );
  const [newArticle, setNewArticle] = useState({
    title: "",
    category: "news",
    excerpt: "",
    content: "",
    author: "Admin User",
    tags: "",
    is_published: false,
    meta_title: "",
    meta_description: "",
  });

  const resetForm = () => {
    setNewArticle({
      title: "",
      category: "news",
      excerpt: "",
      content: "",
      author: "Admin User",
      tags: "",
      is_published: false,
      meta_title: "",
      meta_description: "",
    });
    setImageFile(null);
    setCurrentImagePreview(null);
    setEditingId(null);
  };

  const handleEdit = (article: Article & { meta_title?: string; meta_description?: string }) => {
    setNewArticle({
      title: article.title,
      category: article.category,
      excerpt: article.excerpt || "",
      content: article.content,
      author: article.author?.username || "Admin User",
      tags: article.tags
        ? (article.tags as (string | Tag)[])
          .map((t) => (typeof t === "string" ? t : t.name))
          .join(", ")
        : "",
      is_published: article.is_published || false,
      meta_title: article.meta_title || "",
      meta_description: article.meta_description || "",
    });
    setCurrentImagePreview(article.featured_image || null);
    setEditingId(article.id.toString());
    setIsCreateDialogOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const toastId = toast.loading(editingId ? "Updating article..." : "Creating article...");
    try {
      const formData = new FormData();
      formData.append("title", newArticle.title);
      formData.append("category", newArticle.category);
      formData.append("excerpt", newArticle.excerpt);
      formData.append("content", newArticle.content);
      formData.append("tags", newArticle.tags);
      formData.append("is_published", String(newArticle.is_published));
      formData.append("meta_title", newArticle.meta_title);
      formData.append("meta_description", newArticle.meta_description);

      if (imageFile) {
        formData.append("featured_image", imageFile);
      }

      if (editingId) {
        await adminAPI.updateArticle(editingId, formData);
        toast.success("Article updated successfully", { id: toastId });
      } else {
        await adminAPI.createArticle(formData);
        toast.success("Article created successfully", { id: toastId });
      }

      setIsCreateDialogOpen(false);
      resetForm();
      refetch();
    } catch (error: any) {
      console.error("Failed to save article:", error);
      toast.error(error.message || "Failed to save article", { id: toastId });
    }
  };

  const handlePreview = (article: Article) => {
    if (!article.slug) {
      toast.error("Article slug not found. Save as draft first.");
      return;
    }
    window.open(`/news/${article.slug}`, "_blank");
  };

  const filteredArticles = articles.filter((article: Article) => {
    const matchesSearch =
      (article.title || "").toLowerCase().includes(searchTerm.toLowerCase()) ||
      (article.author?.username || "")
        .toLowerCase()
        .includes(searchTerm.toLowerCase());
    // Category filter is already handled by the API hook, but we can double check or handle 'all'
    // const matchesCategory =
    //   categoryFilter === "all" ||
    //   article.category === categoryFilter ||
    //   (article.categories && article.categories.includes(categoryFilter));
    return matchesSearch; // Category check is largely redundant if API handles it, but harmless
  });

  const handleDelete = async (id: string | number) => {
    if (confirm("Are you sure you want to delete this article?")) {
      try {
        await adminAPI.deleteArticle(id);
        toast.success("Article deleted successfully");
        refetch();
      } catch (error) {
        console.error("Failed to delete article:", error);
        toast.error("Failed to delete article");
      }
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">News & Articles</h1>
          <p className="text-muted-foreground">
            Manage your platform&apos;s editorial content, news, and bike
            reviews.
          </p>
        </div>

        <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
          <DialogTrigger asChild>
            <Button
              className="shrink-0"
              onClick={() => {
                resetForm();
                setIsCreateDialogOpen(true);
              }}
            >
              <Plus className="mr-2 h-4 w-4" /> Create New Article
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
            <form onSubmit={handleSubmit}>
              <DialogHeader>
                <DialogTitle>
                  {editingId ? "Edit Article" : "Create New Article"}
                </DialogTitle>
                <DialogDescription>
                  {editingId
                    ? "Update the article details below."
                    : "Write a new blog post, news update, or bike review. Articles are saved as drafts by default."}
                </DialogDescription>
              </DialogHeader>

              <div className="py-6">
                <Tabs defaultValue="content" className="w-full">
                  <TabsList className="grid w-full grid-cols-2">
                    <TabsTrigger value="content">Article Content</TabsTrigger>
                    <TabsTrigger value="seo">SEO & Settings</TabsTrigger>
                  </TabsList>

                  <TabsContent value="content" className="space-y-6 py-6">
                    <div className="space-y-2">
                      <Label htmlFor="title">Article Title</Label>
                      <Input
                        id="title"
                        placeholder="e.g. Yamaha R15 V4 Launch Event in Dhaka"
                        required
                        value={newArticle.title}
                        onChange={(e) =>
                          setNewArticle({ ...newArticle, title: e.target.value })
                        }
                      />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <Label htmlFor="category">Category</Label>
                        <Select
                          value={newArticle.category}
                          onValueChange={(v) =>
                            setNewArticle({ ...newArticle, category: v })
                          }
                        >
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {CATEGORIES.map((cat: { label: string; value: string }) => (
                              <SelectItem key={cat.value} value={cat.value}>
                                {cat.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="author">Author Name</Label>
                        <Input
                          id="author"
                          value={newArticle.author}
                          onChange={(e) =>
                            setNewArticle({ ...newArticle, author: e.target.value })
                          }
                        />
                      </div>
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="excerpt">Excerpt (Short Summary)</Label>
                      <Textarea
                        id="excerpt"
                        placeholder="Briefly describe what this article is about for the list view..."
                        rows={2}
                        value={newArticle.excerpt}
                        onChange={(e) =>
                          setNewArticle({ ...newArticle, excerpt: e.target.value })
                        }
                      />
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="content">
                        Article Content (Markdown supported)
                      </Label>
                      <Textarea
                        id="content"
                        placeholder="Write your article content here..."
                        rows={12}
                        required
                        value={newArticle.content}
                        onChange={(e) =>
                          setNewArticle({ ...newArticle, content: e.target.value })
                        }
                      />
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="tags">Tags (Comma separated)</Label>
                      <Input
                        id="tags"
                        placeholder="e.g. yamaha, sportbike, launch"
                        value={newArticle.tags}
                        onChange={(e) =>
                          setNewArticle({ ...newArticle, tags: e.target.value })
                        }
                      />
                    </div>

                    <div className="flex items-center gap-4 p-4 border rounded-lg bg-muted/30">
                      <label className="h-20 w-32 border-2 border-dashed rounded flex flex-col items-center justify-center text-muted-foreground cursor-pointer hover:bg-muted/50 transition-colors relative overflow-hidden">
                        {(imageFile || currentImagePreview) ? (
                          <Image
                            src={imageFile ? URL.createObjectURL(imageFile) : getSafeImageUrl(currentImagePreview)}
                            alt="Preview"
                            fill
                            className="object-cover"
                          />
                        ) : (
                          <div className="flex flex-col items-center justify-center text-xs">
                            <ImageIcon className="h-5 w-5 mb-1" />
                            <span>Add Image</span>
                          </div>
                        )}
                        <input
                          type="file"
                          accept="image/*"
                          className="hidden"
                          onChange={(e) => {
                            if (e.target.files?.[0]) {
                              setImageFile(e.target.files[0]);
                            }
                          }}
                        />
                      </label>
                      <p className="text-xs text-muted-foreground">
                        Upload a high-quality featured image (16:9 ratio
                        recommended).
                        <br />
                        Max size: 2MB.
                      </p>
                    </div>

                    <div className="flex items-center justify-between p-4 border rounded-lg bg-primary/5 border-primary/20">
                      <div className="space-y-0.5">
                        <Label htmlFor="is_published" className="text-base">
                          Publish Article
                        </Label>
                        <p className="text-xs text-muted-foreground">
                          Make this article visible on the public website immediately.
                        </p>
                      </div>
                      <Switch
                        id="is_published"
                        checked={newArticle.is_published}
                        onCheckedChange={(checked) =>
                          setNewArticle({ ...newArticle, is_published: checked })
                        }
                      />
                    </div>
                  </TabsContent>

                  <TabsContent value="seo" className="space-y-6 py-6">
                    <div className="space-y-4">
                      <div className="space-y-2">
                        <Label htmlFor="meta_title">Meta Title (SEO)</Label>
                        <Input
                          id="meta_title"
                          placeholder="Search engine optimized title..."
                          value={newArticle.meta_title}
                          onChange={(e) =>
                            setNewArticle({ ...newArticle, meta_title: e.target.value })
                          }
                        />
                        <p className="text-xs text-muted-foreground">
                          Recommended length: 50-60 characters.
                        </p>
                      </div>

                      <div className="space-y-2">
                        <Label htmlFor="meta_description">Meta Description</Label>
                        <Textarea
                          id="meta_description"
                          placeholder="Brief description for search results..."
                          rows={4}
                          value={newArticle.meta_description}
                          onChange={(e) =>
                            setNewArticle({ ...newArticle, meta_description: e.target.value })
                          }
                        />
                        <p className="text-xs text-muted-foreground">
                          Recommended length: 150-160 characters.
                        </p>
                      </div>

                      <div className="p-4 border rounded-lg bg-muted/30 space-y-2">
                        <h4 className="text-sm font-semibold flex items-center gap-2">
                          <Search className="h-4 w-4" /> Search Engine Preview
                        </h4>
                        <div className="space-y-1">
                          <p className="text-blue-600 hover:underline cursor-pointer text-lg font-medium leading-tight">
                            {newArticle.meta_title || newArticle.title || "Article Title Prevew"}
                          </p>
                          <p className="text-green-700 text-sm line-clamp-1">
                            mrbikebd.com › news › {newArticle.title.toLowerCase().replace(/\s+/g, '-')}
                          </p>
                          <p className="text-muted-foreground text-sm line-clamp-2">
                            {newArticle.meta_description || newArticle.excerpt || "Article description preview will appear here when you write a meta description or an excerpt."}
                          </p>
                        </div>
                      </div>
                    </div>
                  </TabsContent>
                </Tabs>
              </div>

              <DialogFooter>
                <Button
                  variant="outline"
                  type="button"
                  onClick={() => setIsCreateDialogOpen(false)}
                >
                  Cancel
                </Button>
                <Button type="submit">
                  <Save className="mr-2 h-4 w-4" /> {editingId ? "Update Article" : "Create Article"}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader className="pb-3">
          <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
            <div className="relative w-full md:w-96">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search by title or author..."
                className="pl-10"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <div className="flex items-center gap-2 w-full md:w-auto">
              <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                <SelectTrigger className="w-full md:w-[180px]">
                  <SelectValue placeholder="All Categories" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Categories</SelectItem>
                  {CATEGORIES.map((cat: { label: string; value: string }) => (
                    <SelectItem key={cat.value} value={cat.value}>
                      {cat.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button variant="outline" size="icon">
                <Filter className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="rounded-md border overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-[80px]">Image</TableHead>
                  <TableHead>Article Details</TableHead>
                  <TableHead>Category</TableHead>
                  <TableHead>Author</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Date</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredArticles.map((article) => (
                  <TableRow key={article.id}>
                    <TableCell>
                      <div className="h-12 w-16 rounded overflow-hidden bg-muted relative">
                        <Image
                          src={getSafeImageUrl(article.featured_image)}
                          alt={article.title}
                          fill
                          className="object-cover"
                        />
                      </div>
                    </TableCell>
                    <TableCell className="max-w-md">
                      <div className="font-medium line-clamp-1">
                        {article.title}
                      </div>
                      <div className="text-xs text-muted-foreground flex items-center gap-2">
                        <Eye className="h-3 w-3" />{" "}
                        {(article.views ?? 0).toLocaleString()} views
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className="capitalize">
                        {article.category}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <div className="h-6 w-6 rounded-full bg-accent flex items-center justify-center">
                          <UserIcon className="h-3 w-3" />
                        </div>
                        <span className="text-sm">{article.author?.username || 'Admin'}</span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge
                        variant={
                          article.is_published
                            ? "default"
                            : "secondary"
                        }
                      >
                        {article.is_published ? "Published" : "Draft"}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                      <div className="flex items-center gap-1">
                        <Calendar className="h-3 w-3" /> {article.published_at ? new Date(article.published_at).toLocaleDateString() : '-'}
                      </div>
                    </TableCell>
                    <TableCell className="text-right">
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon">
                            <MoreVertical className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end" className="w-48">
                          <DropdownMenuLabel>Actions</DropdownMenuLabel>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem onClick={() => handleEdit(article)}>
                            <Edit2 className="mr-2 h-4 w-4" /> Edit Content
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => handlePreview(article)}>
                            <Eye className="mr-2 h-4 w-4" /> Preview
                          </DropdownMenuItem>
                          <DropdownMenuItem>
                            <ArrowUpRight className="mr-2 h-4 w-4" /> Settings &
                            SEO
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem
                            className="text-destructive focus:text-destructive"
                            onClick={() => handleDelete(article.id)}
                          >
                            <Trash2 className="mr-2 h-4 w-4" /> Delete Article
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
                {filteredArticles.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={7} className="h-24 text-center">
                      <div className="flex flex-col items-center justify-center text-muted-foreground">
                        <Newspaper className="h-8 w-8 mb-2 opacity-20" />
                        <p>No articles found matching your filters.</p>
                      </div>
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { Loader2, ShieldCheck, Shield, AlertTriangle, Copy, CheckCircle2, ExternalLink } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "sonner";
import { api } from "@/lib/api-service";

export default function AdminTwoFactorPage() {
  const { data: session, status } = useSession();
  const router = useRouter();

  const [qrCode, setQrCode] = useState<string | null>(null);
  const [secret, setSecret] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isVerifying, setIsVerifying] = useState(false);
  const [verifyCode, setVerifyCode] = useState("");
  const [is2FAEnabled, setIs2FAEnabled] = useState(false);
  const [copied, setCopied] = useState(false);
  const [setupStarted, setSetupStarted] = useState(false);
  const [setupComplete, setSetupComplete] = useState(false);

  useEffect(() => {
    if (status === "unauthenticated") {
      router.push("/login");
    }
  }, [status, router]);

  const handleGetQRCode = async () => {
    setIsLoading(true);
    try {
      const response = await api.get("/users/auth/setup-2fa/");
      const data = response.data as { message?: string; qr_code?: string; secret?: string };
      if (data.message === "2FA is already enabled") {
        setIs2FAEnabled(true);
        toast.info("2FA is already enabled for your account.");
      } else {
        setQrCode(data.qr_code || null);
        setSecret(data.secret || null);
        setSetupStarted(true);
        toast.success("QR code generated! Scan it with your authenticator app.");
      }
    } catch (error: any) {
      if (error.response?.data?.message === "2FA is already enabled") {
        setIs2FAEnabled(true);
        toast.info("2FA is already active on your account.");
      } else {
        toast.error(error.response?.data?.error || "Failed to generate QR code");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifySetup = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!verifyCode || verifyCode.length !== 6) {
      toast.error("Please enter the 6-digit code from your authenticator app");
      return;
    }

    setIsVerifying(true);
    try {
      // Use verify-2fa endpoint with a special "setup" session flag
      await api.post("/users/auth/setup-2fa/", { code: verifyCode });
      setSetupComplete(true);
      toast.success("🎉 2FA verified and activated! Your account is now protected.");
    } catch (error: any) {
      toast.error(error.response?.data?.error || "Invalid code. Please try again.");
      setVerifyCode("");
    } finally {
      setIsVerifying(false);
    }
  };

  const copySecret = () => {
    if (secret) {
      navigator.clipboard.writeText(secret);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
      toast.success("Secret key copied to clipboard!");
    }
  };

  if (status === "loading") {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-10 w-10 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-zinc-950 via-zinc-900 to-zinc-800 p-4 md:p-8">
      <div className="max-w-2xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-3 mb-8">
          <div className="bg-primary/10 border border-primary/20 p-3 rounded-xl">
            <ShieldCheck className="h-6 w-6 text-primary" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-white">Two-Factor Authentication</h1>
            <p className="text-zinc-400 text-sm">Add an extra layer of security to your admin account</p>
          </div>
        </div>

        {/* Status Card */}
        {is2FAEnabled || setupComplete ? (
          <Card className="bg-green-950/40 border-green-500/30">
            <CardContent className="p-6">
              <div className="flex items-center gap-4">
                <CheckCircle2 className="h-10 w-10 text-green-400 shrink-0" />
                <div>
                  <h2 className="text-lg font-bold text-green-300">2FA is Active</h2>
                  <p className="text-green-400/80 text-sm mt-1">
                    Your admin account is protected with two-factor authentication. Every login will require a code from your authenticator app.
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        ) : (
          <>
            {/* Warning */}
            <Card className="bg-amber-950/40 border-amber-500/30 mb-6">
              <CardContent className="p-4 flex items-start gap-3">
                <AlertTriangle className="h-5 w-5 text-amber-400 mt-0.5 shrink-0" />
                <p className="text-amber-300/90 text-sm">
                  2FA is not enabled on your account. Admin accounts must have 2FA enabled for production security.
                </p>
              </CardContent>
            </Card>

            {/* Setup Flow */}
            <Card className="bg-zinc-900/80 border-zinc-700/50">
              <CardHeader>
                <CardTitle className="text-white flex items-center gap-2">
                  <Shield className="h-5 w-5 text-primary" />
                  Set Up Authenticator App
                </CardTitle>
                <CardDescription className="text-zinc-400">
                  Use Google Authenticator, Authy, or any TOTP-compatible app.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                {!setupStarted ? (
                  <div className="space-y-4">
                    <div className="bg-zinc-800/50 rounded-lg p-4 space-y-2">
                      <p className="text-zinc-300 font-medium text-sm">How it works:</p>
                      <ol className="text-zinc-400 text-sm space-y-1 list-decimal list-inside">
                        <li>Click the button below to generate your QR code</li>
                        <li>Open your authenticator app and scan the QR code</li>
                        <li>Enter the 6-digit code to confirm setup</li>
                        <li>From now on, login will require this code</li>
                      </ol>
                    </div>
                    <Button
                      className="w-full h-12 text-base font-semibold"
                      onClick={handleGetQRCode}
                      disabled={isLoading}
                    >
                      {isLoading ? (
                        <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                      ) : (
                        <>
                          <ShieldCheck className="mr-2 h-5 w-5" />
                          Generate QR Code
                        </>
                      )}
                    </Button>
                    <div className="flex items-center gap-2 justify-center">
                      <a
                        href="https://apps.apple.com/app/google-authenticator/id388497605"
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1 text-xs text-primary hover:underline"
                      >
                        <ExternalLink className="h-3 w-3" />
                        Get Google Authenticator (iOS)
                      </a>
                      <span className="text-zinc-600">·</span>
                      <a
                        href="https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2"
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1 text-xs text-primary hover:underline"
                      >
                        <ExternalLink className="h-3 w-3" />
                        Android
                      </a>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-6">
                    {/* QR Code */}
                    {qrCode && (
                      <div className="flex flex-col items-center gap-4">
                        <p className="text-sm text-zinc-300 text-center">
                          Scan this QR code with your authenticator app:
                        </p>
                        <div className="bg-white p-4 rounded-xl shadow-lg">
                          <Image
                            src={`data:image/png;base64,${qrCode}`}
                            alt="2FA QR Code"
                            width={200}
                            height={200}
                          />
                        </div>
                      </div>
                    )}

                    {/* Secret Key (manual entry fallback) */}
                    {secret && (
                      <div className="space-y-2">
                        <p className="text-xs text-zinc-400">
                          Can&apos;t scan? Enter this secret key manually in your app:
                        </p>
                        <div className="flex gap-2">
                          <code className="flex-1 bg-zinc-800 px-3 py-2 rounded-lg text-xs text-zinc-300 font-mono break-all">
                            {secret}
                          </code>
                          <Button
                            size="icon"
                            variant="outline"
                            className="shrink-0 border-zinc-700"
                            onClick={copySecret}
                          >
                            {copied ? (
                              <CheckCircle2 className="h-4 w-4 text-green-400" />
                            ) : (
                              <Copy className="h-4 w-4" />
                            )}
                          </Button>
                        </div>
                      </div>
                    )}

                    {/* Verification */}
                    <form onSubmit={handleVerifySetup} className="space-y-4 pt-2 border-t border-zinc-700/50">
                      <p className="text-sm text-zinc-300 font-medium">
                        Verify setup by entering the code from your app:
                      </p>
                      <div className="space-y-2">
                        <Label htmlFor="verify-code" className="text-zinc-300">
                          6-Digit Code
                        </Label>
                        <Input
                          id="verify-code"
                          type="text"
                          inputMode="numeric"
                          pattern="[0-9]{6}"
                          maxLength={6}
                          placeholder="000000"
                          className="h-14 text-2xl tracking-[0.5em] text-center font-mono bg-zinc-800/50 border-zinc-600 text-white"
                          value={verifyCode}
                          onChange={(e) => setVerifyCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
                          autoFocus
                          autoComplete="one-time-code"
                        />
                      </div>
                      <Button
                        type="submit"
                        className="w-full h-12 text-base font-semibold"
                        disabled={isVerifying || verifyCode.length !== 6}
                      >
                        {isVerifying ? (
                          <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                        ) : (
                          <>
                            <CheckCircle2 className="mr-2 h-5 w-5" />
                            Activate 2FA
                          </>
                        )}
                      </Button>
                    </form>
                  </div>
                )}
              </CardContent>
            </Card>
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
    Save,
    Globe,
    Mail,
    Shield,
    Bell,
    Database,
    Loader,
    Smartphone,
    CheckCircle2,
} from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";
import { adminAPI } from "@/lib/admin-api";

export default function AdminSettings() {
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [settings, setSettings] = useState<any>({
        site_name: "MrBikeBD",
        site_description: "The largest motorcycle marketplace in Bangladesh.",
        contact_email: "support@mrbikebd.com",
        contact_phone: "+880 123456789",
        maintenance_mode: false,
        enable_registration: true,
        require_email_verification: true,
        max_listing_images: 10,
        listing_expiry_days: 90,
    });

    useEffect(() => {
        loadSettings();
    }, []);

    const loadSettings = async () => {
        try {
            setLoading(true);
            const data = await adminAPI.getSettings();
            if (data) setSettings(data);
        } catch (error) {
            console.error("Failed to load settings:", error);
            // Fallback to defaults if API fails
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        try {
            setSaving(true);
            await adminAPI.updateSettings(settings);
            toast.success("Settings saved successfully");
        } catch (error) {
            console.error("Failed to save settings:", error);
            toast.error("Failed to save settings");
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[400px] space-y-4">
                <Loader className="h-8 w-8 animate-spin text-primary" />
                <p className="text-muted-foreground">Loading system settings...</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">System Settings</h1>
                    <p className="text-muted-foreground mt-1">Configure site-wide preferences and platform parameters.</p>
                </div>
                <Button onClick={handleSave} disabled={saving} className="bg-primary hover:bg-primary/90">
                    {saving ? <Loader className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}
                    Save Changes
                </Button>
            </div>

            <Tabs defaultValue="general" className="space-y-6">
                <TabsList className="bg-muted/50 p-1">
                    <TabsTrigger value="general" className="data-[state=active]:bg-background">General</TabsTrigger>
                    <TabsTrigger value="auth" className="data-[state=active]:bg-background">Auth & Security</TabsTrigger>
                    <TabsTrigger value="marketplace" className="data-[state=active]:bg-background">Marketplace</TabsTrigger>
                    <TabsTrigger value="notifications" className="data-[state=active]:bg-background">Notifications</TabsTrigger>
                </TabsList>

                <TabsContent value="general">
                    <Card>
                        <CardHeader>
                            <div className="flex items-center gap-2">
                                <Globe className="h-5 w-5 text-primary" />
                                <CardTitle>General Configuration</CardTitle>
                            </div>
                            <CardDescription>Basic site identity and public information.</CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-6">
                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor="site_name">Site Name</Label>
                                    <Input
                                        id="site_name"
                                        value={settings.site_name}
                                        onChange={(e) => setSettings({ ...settings, site_name: e.target.value })}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="contact_email">Support Email</Label>
                                    <Input
                                        id="contact_email"
                                        type="email"
                                        value={settings.contact_email}
                                        onChange={(e) => setSettings({ ...settings, contact_email: e.target.value })}
                                    />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="site_description">Site Description</Label>
                                <Textarea
                                    id="site_description"
                                    rows={3}
                                    value={settings.site_description}
                                    onChange={(e) => setSettings({ ...settings, site_description: e.target.value })}
                                />
                            </div>
                            <Separator />
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <Label>Maintenance Mode</Label>
                                    <p className="text-sm text-muted-foreground">Temporarily disable public access to the marketplace.</p>
                                </div>
                                <Switch
                                    checked={settings.maintenance_mode}
                                    onCheckedChange={(checked) => setSettings({ ...settings, maintenance_mode: checked })}
                                />
                            </div>
                        </CardContent>
                    </Card>
                </TabsContent>

                <TabsContent value="auth">
                    <Card>
                        <CardHeader>
                            <div className="flex items-center gap-2">
                                <Shield className="h-5 w-5 text-primary" />
                                <CardTitle>Authentication Settings</CardTitle>
                            </div>
                            <CardDescription>Manage user access and verification flows.</CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-6">
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <Label>Allow New Registrations</Label>
                                    <p className="text-sm text-muted-foreground">Enable or disable public account creation.</p>
                                </div>
                                <Switch
                                    checked={settings.enable_registration}
                                    onCheckedChange={(checked) => setSettings({ ...settings, enable_registration: checked })}
                                />
                            </div>
                            <Separator />
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <Label>Enforce Email Verification</Label>
                                    <p className="text-sm text-muted-foreground">Users must verify their email before they can log in.</p>
                                </div>
                                <Switch
                                    checked={settings.require_email_verification}
                                    onCheckedChange={(checked) => setSettings({ ...settings, require_email_verification: checked })}
                                />
                            </div>
                            <Separator />
                            <div className="bg-muted/30 p-4 rounded-lg flex items-start gap-4">
                                <Smartphone className="h-5 w-5 text-muted-foreground mt-0.5" />
                                <div>
                                    <h4 className="text-sm font-semibold">Phone Login Deprecated</h4>
                                    <p className="text-sm text-muted-foreground">SMS/Phone authentication has been disabled in the backend. All new accounts must be created via Email or Google.</p>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </TabsContent>

                <TabsContent value="marketplace">
                    <Card>
                        <CardHeader>
                            <div className="flex items-center gap-2">
                                <Database className="h-5 w-5 text-primary" />
                                <CardTitle>Marketplace Parameters</CardTitle>
                            </div>
                            <CardDescription>Control listing constraints and behavior.</CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-6">
                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor="max_images">Max Images per Listing</Label>
                                    <Input
                                        id="max_images"
                                        type="number"
                                        value={settings.max_listing_images}
                                        onChange={(e) => setSettings({ ...settings, max_listing_images: parseInt(e.target.value) })}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="expiry">Listing Expiry (Days)</Label>
                                    <Input
                                        id="expiry"
                                        type="number"
                                        value={settings.listing_expiry_days}
                                        onChange={(e) => setSettings({ ...settings, listing_expiry_days: parseInt(e.target.value) })}
                                    />
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </TabsContent>

                <TabsContent value="notifications">
                    <Card>
                        <CardHeader>
                            <div className="flex items-center gap-2">
                                <Bell className="h-5 w-5 text-primary" />
                                <CardTitle>Email & Notifications</CardTitle>
                            </div>
                            <CardDescription>Configure how the system communicates with users.</CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-6">
                            <div className="bg-green-500/5 border border-green-500/20 p-4 rounded-lg flex items-start gap-4">
                                <CheckCircle2 className="h-5 w-5 text-green-600 mt-0.5" />
                                <div>
                                    <h4 className="text-sm font-semibold text-green-900">Brevo SDK Active</h4>
                                    <p className="text-sm text-green-800/80">The system is currently using the official Brevo Python SDK for all transactional emails.</p>
                                </div>
                            </div>
                            <div className="grid gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="sender_name">Default Sender Name</Label>
                                    <Input id="sender_name" value="MrBikeBD Support" disabled />
                                    <p className="text-[10px] text-muted-foreground">Configured in server environment variables.</p>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </TabsContent>
            </Tabs>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import Image from "next/image";
import { cn } from "@/lib/utils";
import {
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  Eye,
  MoreHorizontal,
  Bike,
  Calendar,
  MapPin,
  Tag,
  Users,
  Loader,
  AlertTriangle,
  Scale,
  Fuel,
  Info,
  Trash2,
} from "lucide-react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { adminAPI, UsedBikeListing } from "@/lib/admin-api";
import { sanitizeImageUrl } from "@/lib/data-utils";

const BIKE_CATEGORIES = [
  { value: "sports", label: "Sports" },
  { value: "naked", label: "Naked Sport" },
  { value: "cruiser", label: "Cruiser" },
  { value: "commuter", label: "Commuter" },
  { value: "scooter", label: "Scooter" },
  { value: "adventure", label: "Adventure" },
  { value: "cafe_racer", label: "Cafe Racer" },
  { value: "offroad", label: "Off-Road" },
];

export default function UsedBikesModeration() {
  const [listings, setListings] = useState<UsedBikeListing[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterStatus, setFilterStatus] = useState<
    "all" | "pending" | "active" | "rejected" | "sold"
  >("pending");
  const [approvingId, setApprovingId] = useState<number | null>(null);
  const [rejectingId, setRejectingId] = useState<number | null>(null);
  const [deletingId, setDeletingId] = useState<number | null>(null);
  const [rejectDialog, setRejectDialog] = useState<{
    open: boolean;
    id: number | null;
    reason: string;
  }>({
    open: false,
    id: null,
    reason: "",
  });
  const [previewDialog, setPreviewDialog] = useState<{
    open: boolean;
    listing: UsedBikeListing | null;
  }>({
    open: false,
    listing: null,
  });
  const [approveDialog, setApproveDialog] = useState<{
    open: boolean;
    id: number | null;
    category: string;
  }>({
    open: false,
    id: null,
    category: "commuter",
  });

  useEffect(() => {
    loadListings("pending");
  }, []);

  const loadListings = async (status?: string) => {
    try {
      setLoading(true);
      const response = await adminAPI.getAllUsedBikes({
        limit: 100,
        offset: 0,
        sort: "newest",
        status: (status === "all" ? undefined : status) as "pending" | "active" | "rejected" | "sold" | undefined,
      });
      setListings(response.results || response);
    } catch (error) {
      console.error("Failed to load listings:", error);
      toast.error("Failed to load listings");
    } finally {
      setLoading(false);
    }
  };

  const handleApproveSubmit = async () => {
    if (!approveDialog.id) return;

    try {
      setApprovingId(approveDialog.id);
      await adminAPI.approveListing(approveDialog.id, approveDialog.category);
      toast.success("Listing approved successfully");
      setListings(
        listings.map((l) =>
          l.id === approveDialog.id ? { ...l, status: "active" } : l,
        ),
      );
      setApproveDialog({ open: false, id: null, category: "commuter" });
    } catch (error) {
      console.error("Failed to approve listing:", error);
      toast.error("Failed to approve listing");
    } finally {
      setApprovingId(null);
    }
  };

  const handleRejectSubmit = async () => {
    if (!rejectDialog.id) return;

    try {
      setRejectingId(rejectDialog.id);
      await adminAPI.rejectListing(
        rejectDialog.id,
        rejectDialog.reason || "Rejected by admin",
      );
      toast.success("Listing rejected");
      setListings(
        listings.map((l) =>
          l.id === rejectDialog.id ? { ...l, status: "rejected" } : l,
        ),
      );
      setRejectDialog({ open: false, id: null, reason: "" });
    } catch (error) {
      console.error("Failed to reject listing:", error);
      toast.error("Failed to reject listing");
    } finally {
      setRejectingId(null);
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm("Are you sure you want to permanently delete this listing?"))
      return;

    try {
      setDeletingId(id);
      await adminAPI.deleteUsedBike(id);
      toast.success("Listing deleted successfully");
      setListings(listings.filter((l) => l.id !== id));
    } catch (error) {
      console.error("Failed to delete listing:", error);
      toast.error("Failed to delete listing");
    } finally {
      setDeletingId(null);
    }
  };

  const filteredListings = listings.filter((listing) => {
    const matchesSearch =
      listing.bike_model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      listing.seller_name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      listing.brand.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus =
      filterStatus === "all" || listing.status === filterStatus;
    return matchesSearch && matchesStatus;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">
            Used Bike Moderation
          </h1>
          <p className="text-muted-foreground mt-1">
            Review and manage user-submitted advertisements.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm">
            <Filter className="mr-2 h-4 w-4" /> Filter
          </Button>
        </div>
      </div>

      <Card>
        <CardHeader>
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="relative flex-1 max-w-sm">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search by bike or seller..."
                className="pl-9"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            <div className="flex items-center gap-2">
              <Button
                variant={filterStatus === "all" ? "default" : "outline"}
                size="sm"
                onClick={() => {
                  setFilterStatus("all");
                  loadListings("all");
                }}
              >
                All
              </Button>
              <Button
                variant={filterStatus === "pending" ? "default" : "outline"}
                size="sm"
                onClick={() => {
                  setFilterStatus("pending");
                  loadListings("pending");
                }}
                className={cn(
                  filterStatus === "pending" &&
                  "bg-yellow-600 hover:bg-yellow-700",
                )}
              >
                Pending
              </Button>
              <Button
                variant={filterStatus === "active" ? "default" : "outline"}
                size="sm"
                onClick={() => {
                  setFilterStatus("active");
                  loadListings("active");
                }}
                className={cn(
                  filterStatus === "active" &&
                  "bg-green-600 hover:bg-green-700",
                )}
              >
                Active
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex justify-center items-center py-12">
              <Loader className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : (
            <div className="rounded-md border overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="bg-muted/50">
                    <TableHead className="w-[80px]">Image</TableHead>
                    <TableHead>Bike / Brand</TableHead>
                    <TableHead>Seller</TableHead>
                    <TableHead>Location / Year</TableHead>
                    <TableHead>Category</TableHead>
                    <TableHead>Price</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredListings.length > 0 ? (
                    filteredListings.map((listing) => (
                      <TableRow
                        key={listing.id}
                        className="group transition-colors hover:bg-muted/30"
                      >
                        <TableCell>
                          <div className="h-12 w-16 rounded overflow-hidden bg-muted relative">
                            {(() => {
                              const imageUrl = sanitizeImageUrl(
                                (listing as any).image_url || 
                                (listing as any).thumbnail_url || 
                                (listing as any).images?.[0]?.url || 
                                (listing as any).images?.[0], 
                                undefined
                              );
                              return imageUrl ? (
                                <Image
                                  src={imageUrl}
                                  alt={listing.bike_model}
                                  fill
                                  className="object-cover"
                                  unoptimized
                                />
                              ) : (
                                <div className="h-full w-full flex items-center justify-center">
                                  <Bike className="h-6 w-6 text-muted-foreground" />
                                </div>
                              );
                            })()}
                          </div>
                        </TableCell>
                        <TableCell>
                          <div>
                            <p className="font-medium">{listing.bike_model}</p>
                            <p className="text-xs text-muted-foreground capitalize">
                              {listing.brand}
                            </p>
                            {listing.reports_count && listing.reports_count > 0 ? (
                              <div className="flex items-center mt-1 text-xs text-red-500 font-medium">
                                <AlertTriangle className="mr-1 h-3 w-3" />
                                {listing.reports_count} {listing.reports_count === 1 ? 'Report' : 'Reports'}
                              </div>
                            ) : null}
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="font-medium">
                            {listing.seller_name}
                          </div>
                          <p className="text-xs text-muted-foreground">
                            {listing.seller_phone}
                          </p>
                        </TableCell>
                        <TableCell>
                          <div className="space-y-1">
                            <div className="flex items-center text-xs text-muted-foreground">
                              <MapPin className="mr-1 h-3 w-3" />{" "}
                                {typeof listing.seller_location === 'object' ? (listing.seller_location as any).full : listing.seller_location}
                            </div>
                            <div className="flex items-center text-xs text-muted-foreground">
                              <Calendar className="mr-1 h-3 w-3" />{" "}
                              {listing.year}
                            </div>
                          </div>
                        </TableCell>
                        <TableCell>
                          <Badge variant="outline" className="capitalize">
                            {listing.category || 'Commuter'}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center font-bold">
                            <Tag className="mr-1.5 h-3.5 w-3.5 text-primary opacity-70" />
                            ৳{listing.price.toLocaleString()}
                          </div>
                        </TableCell>
                        <TableCell>
                          <Badge
                            className={cn(
                              listing.status === "pending" &&
                              "bg-yellow-100 text-yellow-700 hover:bg-yellow-100 dark:bg-yellow-900/30 dark:text-yellow-400",
                              listing.status === "active" &&
                              "bg-green-100 text-green-700 hover:bg-green-100 dark:bg-green-900/30 dark:text-green-400",
                              listing.status === "rejected" &&
                              "bg-red-100 text-red-700 hover:bg-red-100 dark:bg-red-900/30 dark:text-red-400",
                            )}
                          >
                            {listing.status.charAt(0).toUpperCase() +
                              listing.status.slice(1)}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-2">
                            <Button
                              size="icon"
                              variant="outline"
                              className="h-8 w-8 text-primary hover:text-primary hover:bg-primary/5"
                              onClick={() =>
                                setPreviewDialog({
                                  open: true,
                                  listing: listing,
                                })
                              }
                            >
                              <Eye className="h-4 w-4" />
                            </Button>
                            {listing.status === "pending" && (
                              <>
                                <Button
                                  size="icon"
                                  variant="outline"
                                  className="h-8 w-8 text-green-600 hover:text-green-700 hover:bg-green-50"
                                  onClick={() =>
                                    setApproveDialog({
                                      open: true,
                                      id: listing.id,
                                      category: listing.category || "commuter",
                                    })
                                  }
                                  disabled={approvingId === listing.id}
                                >
                                  {approvingId === listing.id ? (
                                    <Loader className="h-4 w-4 animate-spin" />
                                  ) : (
                                    <CheckCircle2 className="h-4 w-4" />
                                  )}
                                </Button>
                                <Button
                                  size="icon"
                                  variant="outline"
                                  className="h-8 w-8 text-red-600 hover:text-red-700 hover:bg-red-50"
                                  onClick={() =>
                                    setRejectDialog({
                                      open: true,
                                      id: listing.id,
                                      reason: "",
                                    })
                                  }
                                  disabled={rejectingId === listing.id}
                                >
                                  {rejectingId === listing.id ? (
                                    <Loader className="h-4 w-4 animate-spin" />
                                  ) : (
                                    <XCircle className="h-4 w-4" />
                                  )}
                                </Button>
                              </>
                            )}
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button
                                  size="icon"
                                  variant="ghost"
                                  className="h-8 w-8"
                                  disabled={deletingId === listing.id}
                                >
                                  <MoreHorizontal className="h-4 w-4" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end">
                                <DropdownMenuLabel>Actions</DropdownMenuLabel>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem onClick={() => setPreviewDialog({ open: true, listing: listing })}>
                                  <Eye className="mr-2 h-4 w-4" /> Preview Full Ad
                                </DropdownMenuItem>
                                <DropdownMenuItem disabled>
                                  <Users className="mr-2 h-4 w-4" /> Contact
                                  Seller
                                </DropdownMenuItem>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem
                                  className="text-destructive"
                                  onClick={() => handleDelete(listing.id)}
                                  disabled={deletingId === listing.id}
                                >
                                  {deletingId === listing.id ? (
                                    <>
                                      <Loader className="mr-2 h-4 w-4 animate-spin" />{" "}
                                      Deleting...
                                    </>
                                  ) : (
                                    "Delete Listing"
                                  )}
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell
                        colSpan={7}
                        className="h-32 text-center text-muted-foreground"
                      >
                        {listings.length === 0
                          ? "No listings yet."
                          : "No listings found matching your criteria."}
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Reject Dialog */}
      <Dialog
        open={rejectDialog.open}
        onOpenChange={(open) => {
          if (!open) setRejectDialog({ open: false, id: null, reason: "" });
          else setRejectDialog({ ...rejectDialog, open: true });
        }}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Reject Listing</DialogTitle>
            <DialogDescription>
              Provide a reason for rejecting this listing. The seller will be
              notified.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="reason">Reason (optional)</Label>
              <Textarea
                id="reason"
                placeholder="e.g., Low quality images, Missing specifications, Suspicious pricing..."
                rows={4}
                value={rejectDialog.reason}
                onChange={(e) =>
                  setRejectDialog({ ...rejectDialog, reason: e.target.value })
                }
              />
            </div>
            <div className="flex gap-2 justify-end">
              <Button
                variant="outline"
                onClick={() =>
                  setRejectDialog({ open: false, id: null, reason: "" })
                }
                disabled={rejectingId === rejectDialog.id}
              >
                Cancel
              </Button>
              <Button
                variant="destructive"
                onClick={handleRejectSubmit}
                disabled={rejectingId === rejectDialog.id}
              >
                {rejectingId === rejectDialog.id ? (
                  <>
                    <Loader className="mr-2 h-4 w-4 animate-spin" />{" "}
                    Rejecting...
                  </>
                ) : (
                  "Reject"
                )}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
      {/* Approve Dialog */}
      <Dialog
        open={approveDialog.open}
        onOpenChange={(open) => {
          if (!open)
            setApproveDialog({ open: false, id: null, category: "commuter" });
          else setApproveDialog({ ...approveDialog, open: true });
        }}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Approve Listing</DialogTitle>
            <DialogDescription>
              Select a category for this bike before approving.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="category">Category</Label>
              <Select
                value={approveDialog.category}
                onValueChange={(val) =>
                  setApproveDialog({ ...approveDialog, category: val })
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select Category" />
                </SelectTrigger>
                <SelectContent>
                  {BIKE_CATEGORIES.map((cat) => (
                    <SelectItem key={cat.value} value={cat.value}>
                      {cat.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="flex gap-2 justify-end">
              <Button
                variant="outline"
                onClick={() =>
                  setApproveDialog({
                    open: false,
                    id: null,
                    category: "commuter",
                  })
                }
                disabled={approvingId === approveDialog.id}
              >
                Cancel
              </Button>
              <Button
                className="bg-green-600 hover:bg-green-700"
                onClick={handleApproveSubmit}
                disabled={approvingId === approveDialog.id}
              >
                {approvingId === approveDialog.id ? (
                  <>
                    <Loader className="mr-2 h-4 w-4 animate-spin" />{" "}
                    Approving...
                  </>
                ) : (
                  "Approve & Publish"
                )}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
      
      {/* Preview Full Detail Dialog */}
      <Dialog
        open={previewDialog.open}
        onOpenChange={(open) => {
          if (!open) setPreviewDialog({ open: false, listing: null });
          else setPreviewDialog({ ...previewDialog, open: true });
        }}
      >
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Listing Details</DialogTitle>
            <DialogDescription>
              Review all information provided by the seller.
            </DialogDescription>
          </DialogHeader>

          {previewDialog.listing && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 py-4">
              <div className="space-y-6">
                <div className="relative aspect-video rounded-lg overflow-hidden bg-muted border">
                  { ((previewDialog.listing.images?.length ?? 0) > 0 || previewDialog.listing.image_url) ? (
                    <Image
                      src={sanitizeImageUrl(previewDialog.listing.images?.[0]?.url || previewDialog.listing.images?.[0] || previewDialog.listing.image_url)}
                      alt={previewDialog.listing.title || previewDialog.listing.bike_model}
                      fill
                      className="object-cover"
                      unoptimized
                    />
                  ) : (
                    <div className="h-full w-full flex items-center justify-center">
                      <Bike className="h-12 w-12 text-muted-foreground opacity-20" />
                    </div>
                  )}
                  <div className="absolute top-2 right-2">
                    <Badge variant={previewDialog.listing.status === 'active' ? 'default' : 'secondary'}>
                      {previewDialog.listing.status.toUpperCase()}
                    </Badge>
                  </div>
                </div>

                <div className="space-y-4">
                  <h3 className="font-semibold text-lg flex items-center gap-2">
                    <Info className="h-4 w-4 text-primary" />
                    Specifications
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="p-3 rounded-lg bg-muted/50">
                      <p className="text-xs text-muted-foreground">Year</p>
                      <p className="font-medium">{previewDialog.listing.year}</p>
                    </div>
                    <div className="p-3 rounded-lg bg-muted/50">
                      <p className="text-xs text-muted-foreground">Engine CC</p>
                      <p className="font-medium">{previewDialog.listing.engine_cc || 'N/A'} CC</p>
                    </div>
                    <div className="p-3 rounded-lg bg-muted/50">
                      <p className="text-xs text-muted-foreground">Mileage</p>
                      <p className="font-medium">{previewDialog.listing.mileage.toLocaleString()} km</p>
                    </div>
                    <div className="p-3 rounded-lg bg-muted/50">
                      <p className="text-xs text-muted-foreground">Condition</p>
                      <p className="font-medium capitalize">{previewDialog.listing.condition.replace('_', ' ')}</p>
                    </div>
                    <div className="p-3 rounded-lg bg-muted/50">
                      <p className="text-xs text-muted-foreground">Location</p>
                      <p className="font-medium truncate">{typeof previewDialog.listing.seller_location === 'object' ? (previewDialog.listing.seller_location as any).city : previewDialog.listing.seller_location}</p>
                    </div>
                    <div className="p-3 rounded-lg bg-muted/50">
                      <p className="text-xs text-muted-foreground">Ownership</p>
                      <p className="font-medium">{previewDialog.listing.ownership_count || 1} Owner(s)</p>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  <h3 className="font-semibold text-sm flex items-center gap-2 text-muted-foreground uppercase tracking-wider">
                    <Info className="h-4 w-4" />
                    Registration & Condition
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="p-3 rounded-lg bg-muted/50">
                      <p className="text-xs text-muted-foreground">Reg. Year</p>
                      <p className="font-medium">{previewDialog.listing.registration_year || 'Not Registered'}</p>
                    </div>
                    <div className="p-3 rounded-lg bg-muted/50">
                      <p className="text-xs text-muted-foreground">Reg. Type</p>
                      <p className="font-medium">{previewDialog.listing.registration_type || 'N/A'}</p>
                    </div>
                    <div className="p-3 rounded-lg bg-muted/50">
                      <p className="text-xs text-muted-foreground">Engine Cond.</p>
                      <p className="font-medium">{previewDialog.listing.engine_condition || 'N/A'}</p>
                    </div>
