                        </p>
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex flex-col gap-2 pt-4">
                  {previewDialog.listing.status === 'pending' && (
                    <div className="grid grid-cols-2 gap-3">
                      <Button 
                        className="bg-green-600 hover:bg-green-700"
                        onClick={() => {
                          setPreviewDialog({ open: false, listing: null });
