          usbPort: !!bike.detailed_specs?.usb_charging,
          sideStandCutOff: !!bike.detailed_specs?.side_stand_cut_off,
          projectorHeadlight: !!bike.detailed_specs?.projector_headlight,
          drls: !!bike.detailed_specs?.drls,
          gearIndicator: !!bike.detailed_specs?.gear_indicator,
          distanceToEmpty: !!bike.detailed_specs?.distance_to_empty,
          avgFuelConsumption: !!bike.detailed_specs?.avg_fuel_consumption,
          pros: {},
          cons: {},
        };
      });
    } else {
      // Create a default variant from the bike model itself if no variants exist
      variantsMap["std"] = {
        fullName:
          `${bike.brand?.name || bike.brand_name || ""} ${bike.name}`.trim(),
        label: "Standard",
        price: Number(bike.price) || Number(bike.priceRange?.min) || 0,
        images: bike.images || [bike.primary_image || "/placeholder-bike.png"],
        quickSpecs: {
          engineCapacity:
            bike.detailed_specs?.displacement ||
            (bike.engine_capacity ? `${bike.engine_capacity} cc` : "N/A"),
          transmission:
            bike.detailed_specs?.gearbox ||
            (bike.gears ? `${bike.gears} Speed` : "N/A"),
          maxPower: bike.detailed_specs?.max_power || bike.max_power || "N/A",
          maxTorque:
            bike.detailed_specs?.max_torque || bike.max_torque || "N/A",
          fuelTank:
            bike.detailed_specs?.fuel_tank_capacity ||
            (bike.fuel_capacity ? `${bike.fuel_capacity} L` : "N/A"),
          kerbWeight:
            bike.detailed_specs?.kerb_weight ||
            (bike.curb_weight ? `${bike.curb_weight} kg` : "N/A"),
          mileageCompany: "N/A",
          mileageUser: "N/A",
          topspeedCompany: "N/A",
          topspeedUser: "N/A",
          fuelType: bike.detailed_specs?.fuel_system || "Petrol",
        },
        fuelEfficiency: "N/A",
        frontTire: bike.detailed_specs?.tyres_front || bike.tyre_type || "N/A",
        rearTire: bike.detailed_specs?.tyres_rear || bike.tyre_type || "N/A",
        brakingSystem: bike.detailed_specs?.braking_system || "N/A",
        headlightType: bike.detailed_specs?.lighting?.headlight || "N/A",
        abs: false,
        ledHeadlight: false,
        usbPort: false,
        pros: {},
        cons: {},
      };
    }

    return variantsMap;
  }, [bike]);

  const variantKeys = Object.keys(variants);
  const currentVariant =
    variants[selectedVariantKey] || variants[variantKeys[0]];

  const defaultImage = bike?.primary_image || "/placeholder-bike.png";

  if (isLoading) {
    return <BikeDetailSkeleton />;
  }

  if (error || !bike) {
    return (
      <div className="w-full px-4 md:px-8 py-16 text-center">
        <h1 className="text-2xl font-bold mb-4">Bike Not Found</h1>
        <p className="text-muted-foreground mb-8">
          The bike you&apos;re looking for doesn&apos;t exist or has been
          removed.
        </p>
        <Button asChild>
          <Link href="/bikes">Browse All Bikes</Link>
        </Button>
      </div>
    );
  }

  // Use API data
  const bikeName = currentVariant?.fullName || bike?.name || "";
  const brandName = bike?.brand?.name || bike?.brand_name || "";
  const basePrice = currentVariant?.price || bike?.priceRange?.min || 0;
  const bikeRating = bike?.rating?.average || 4.5;
  const bikeId = String(bike?.id ?? slug);
  const bikeDescription = bike?.description || "";
  const totalReviews = reviews?.length || 0;

  const isFavorited = isInFavorites(bikeId);
  const isInCompare = bike ? isBikeSelected(String(bike.id)) : false;

  const downPayment = basePrice * (EMI_CONFIG.downPaymentPercent / 100);
  const loanAmount = basePrice - downPayment;
  const emi = calculateEMI(
    loanAmount,
    EMI_CONFIG.defaultInterestRate,
    emiMonths,
  );

  const handleCompareToggle = () => {
    if (!bike || !storesReady) return;
    const id = String(bike.id);
    if (isInCompare) {
      removeBike(id);
    } else {
      addBike(bike);
    }
  };

  const handleFavoriteClick = () => {
    if (!storesReady) return;
    toggleFavorite(bikeId);
  };

  const handleVariantChange = (variantKey: string) => {
    setSelectedVariantKey(variantKey);
    setActiveImageIndex(0);
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Breadcrumb */}
      <div className="bg-muted/50 border-b">
        <div className="w-full px-4 md:px-8 py-3">
          <nav className="flex items-center gap-2 text-sm text-muted-foreground">
            <Link href="/" className="hover:text-foreground">
              Home
            </Link>
            <ChevronRight className="h-4 w-4" />
            <Link href="/bikes" className="hover:text-foreground">
              Bikes
            </Link>
            {brandName && (
              <>
                <ChevronRight className="h-4 w-4" />
                <Link
                  href={`/brands/${brandName.toLowerCase()}`}
                  className="hover:text-foreground"
                >
                  {brandName}
                </Link>
              </>
            )}
            <ChevronRight className="h-4 w-4" />
            <span className="text-foreground font-medium">{bikeName}</span>
          </nav>
        </div>
      </div>

      {/* Hero Section */}
      <section className="w-full px-4 md:px-8 py-6 md:py-10">
        {/* Top Row: Name/Rating (left) + Action Buttons (right) */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-6">
          <div>
            <p className="text-muted-foreground text-sm mb-1">{brandName}</p>
            <h1 className="text-2xl md:text-3xl lg:text-4xl font-bold">
              {bikeName}
            </h1>
            <div className="flex items-center gap-2 mt-2">
              <div className="flex items-center gap-1">
                <Star className="h-5 w-5 fill-yellow-400 text-yellow-400" />
                <span className="font-semibold">{bikeRating.toFixed(1)}</span>
              </div>
              <span className="text-muted-foreground text-sm">
                ({totalReviews} {totalReviews === 1 ? "review" : "reviews"})
              </span>
            </div>
          </div>
          <div className="flex gap-2">
            <Button
              type="button"
              variant={isFavorited ? "default" : "outline"}
              size="sm"
              onClick={handleFavoriteClick}
              disabled={!storesReady}
              className="gap-2"
            >
              <Heart className={cn("h-4 w-4", isFavorited && "fill-current")} />
              {isFavorited ? "Saved to Favorites" : "Add to Favorites"}
            </Button>
            <Button
              type="button"
              variant={isInCompare ? "default" : "outline"}
              size="sm"
              onClick={handleCompareToggle}
              disabled={!bike || !storesReady}
              className="gap-2 hover:bg-primary hover:text-white transition-colors"
            >
              {isInCompare ? (
                <Check className="h-4 w-4 fill-current" />
              ) : (
                <ArrowLeftRight className="h-4 w-4" />
              )}
              {isInCompare ? "In Compare" : "Add to Compare"}
            </Button>
          </div>
        </div>

        {/* Main Content: Image Carousel + Variant/Specs Panel */}
        <div className="grid lg:grid-cols-2 gap-6">
          {/* Image Carousel (takes 1 column) */}
          <div className="space-y-3">
            {/* Main Image */}
            <div className="relative h-[300px] sm:h-[400px] lg:h-[500px] w-full rounded-xl overflow-hidden bg-muted">
              <motion.div
                key={activeImageIndex}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 0.3 }}
                className="w-full h-full relative"
              >
                <Image
                  src={bike.images && bike.images.length > 0 ? bike.images[activeImageIndex] : defaultImage}
                  alt={`${bikeName} - Image ${activeImageIndex + 1}`}
                  fill
                  className="object-cover"
                  priority
                />
              </motion.div>

              {/* Navigation Arrows */}
              <button
                onClick={() =>
                  setActiveImageIndex((prev) =>
                    prev === 0 ? (bike.images?.length || 1) - 1 : prev - 1,
                  )
                }
                className="absolute left-3 top-1/2 -translate-y-1/2 p-2 rounded-full bg-black/50 text-white hover:bg-black/70 transition-colors"
              >
                <ChevronLeft className="h-5 w-5" />
              </button>
              <button
                onClick={() =>
                  setActiveImageIndex((prev) =>
                    prev === (bike.images?.length || 1) - 1 ? 0 : prev + 1,
                  )
                }
                className="absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-full bg-black/50 text-white hover:bg-black/70 transition-colors"
              >
                <ChevronRight className="h-5 w-5" />
              </button>

              {/* Category Badge */}
              <Badge className="absolute top-3 left-3 capitalize">
                {bike?.category || "sport"}
              </Badge>

              {/* Image Counter */}
              <div className="absolute bottom-3 right-3 px-3 py-1 rounded-full bg-black/60 text-white text-sm font-medium">
                {activeImageIndex + 1} / {bike.images?.length || 1}
              </div>
            </div>

            {/* Thumbnails */}
            <div className="flex gap-2 overflow-x-auto hide-scrollbar pb-1">
              {(bike.images || [defaultImage]).map((img, index) => (
                <button
                  key={index}
                  onClick={() => setActiveImageIndex(index)}
                  className={cn(
                    "relative shrink-0 w-16 h-12 md:w-20 md:h-14 rounded-lg overflow-hidden border-2 transition-all",
                    activeImageIndex === index
                      ? "border-primary ring-2 ring-primary/20"
                      : "border-transparent opacity-60 hover:opacity-100",
                  )}
                >
                  <Image
                    src={img}
                    alt={`Thumbnail ${index + 1}`}
                    fill
                    className="object-cover"
                  />
                </button>
              ))}
            </div>
          </div>

          {/* Right Panel: Variant Selector + Quick Specs */}
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
            {/* Variant Selector */}
            <div className="bg-card border rounded-xl p-4 flex flex-col h-full">
              <h3 className="font-semibold text-sm mb-3">Select Variant</h3>
              <div className="flex-1 overflow-y-auto space-y-2 pr-1">
                {variantKeys.map((key) => (
                  <button
                    key={key}
                    onClick={() => handleVariantChange(key)}
                    className={cn(
                      "w-full text-left px-3 py-2.5 rounded-lg border text-sm transition-all",
                      selectedVariantKey === key
                        ? "border-primary bg-primary/10 text-primary font-medium"
                        : "border-border hover:border-primary/50 hover:bg-muted/50",
                    )}
                  >
                    <div className="flex items-center justify-between gap-2">
                      <span className="truncate">{variants[key].label}</span>
                      <span className="text-xs font-medium shrink-0">
                        {formatPrice(variants[key].price)}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            </div>

            {/* Quick Specifications */}
            <QuickSpecsPanel currentVariant={currentVariant} />
          </div>
        </div>

        {/* Bottom Row: Price Info + Similar Used Bikes */}
        <div className="grid lg:grid-cols-2 gap-6 mt-6">
          {/* Price Information */}
          <div className="bg-card border rounded-xl p-5 overflow-hidden">
            <h3 className="font-semibold mb-4">Price Information</h3>
            <div className="space-y-4">
              {/* Price */}
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-1 sm:gap-4 min-w-0">
                <span className="text-muted-foreground text-sm sm:text-base">
                  Ex-showroom Price
                </span>
                <span className="text-xl sm:text-2xl font-bold text-primary whitespace-nowrap">
                  {formatPrice(basePrice)}
                </span>
              </div>

              {/* Estimated EMI */}
              <div className="flex flex-col sm:flex-row sm:items-center justify-between py-3 border-t border-b gap-2 sm:gap-4 min-w-0">
                <div className="min-w-0">
                  <span className="text-muted-foreground text-sm">
                    Estimated EMI
                  </span>
                  <p className="text-[10px] sm:text-xs text-muted-foreground truncate">
                    {EMI_CONFIG.downPaymentPercent}% down,{" "}
                    {EMI_CONFIG.defaultInterestRate}% rate, {emiMonths} months
                  </p>
                </div>
                <span className="text-base sm:text-lg font-semibold text-primary whitespace-nowrap">
                  {formatPrice(emi)}/mo
                </span>
              </div>

              {/* EMI Calculator Link */}
              <Button variant="outline" className="w-full gap-2" asChild>
                <Link href="/emi-calculator">
                  <Calculator className="h-4 w-4" />
                  Open Full EMI Calculator
                </Link>
              </Button>
            </div>
          </div>

          {/* Emotional Triggers: Personalized Used Bike Recommendations */}
          <div className="lg:col-span-2">
            <EmotionalTriggers slug={slug} bikeName={bike.name} />
          </div>
        </div>

        {/* Variant Comparison & Similar Bikes Section */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-6">
          <div className="lg:col-span-2">
            <VariantComparison variants={variants} />
          </div>
          <div className="lg:col-span-1">
            <div className="sticky top-24 space-y-6">
              <SimilarNewBikes slug={slug} />
              <AdMediumRectangle />
            </div>
          </div>
        </div>
      </section>

      {/* Full Specifications Section */}
      <section className="w-full px-4 md:px-8 py-8">
        <div className="bg-card rounded-xl border p-6">
          <h2 className="text-2xl font-bold mb-4">Full Specifications</h2>

          {/* Variant Selector for Specs */}
          {variantKeys.length > 1 && (
            <div className="mb-6">
              <Label className="text-sm font-medium mb-2 block">
                Select Variant to View Specifications
              </Label>
              <Select
                value={selectedVariantKey}
                onValueChange={setSelectedVariantKey}
              >
                <SelectTrigger className="w-64">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {variantKeys.map((key) => (
                    <SelectItem key={key} value={key}>
                      {variants[key].label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Specs Tabs */}
          <Tabs value={specsTab} onValueChange={setSpecsTab} className="w-full">
            {/* Mobile Select */}
            <div className="lg:hidden mb-6">
              <Select value={specsTab} onValueChange={setSpecsTab}>
                <SelectTrigger className="w-full">
                  <SelectValue placeholder="Select Section" />
                </SelectTrigger>
                <SelectContent>
                  {[
                    { id: "engine", label: "Engine & Performance" },
                    { id: "transmission", label: "Transmission & Brakes" },
                    { id: "dimensions", label: "Dimensions & Weight" },
                    { id: "features", label: "Features & Electricals" },
                  ].map((tab) => (
                    <SelectItem key={tab.id} value={tab.id}>
                      {tab.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Desktop TabsList */}
            <TabsList className="hidden lg:flex w-full justify-start border-b rounded-none h-auto p-0 bg-transparent mb-6 overflow-x-auto">
              {[
                { id: "engine", label: "Engine & Performance" },
                { id: "transmission", label: "Transmission & Brakes" },
                { id: "dimensions", label: "Dimensions & Weight" },
                { id: "features", label: "Features & Electricals" },
              ].map((tab) => (
                <TabsTrigger
                  key={tab.id}
                  value={tab.id}
                  className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-4 py-3 text-sm whitespace-nowrap"
                >
                  {tab.label}
                </TabsTrigger>
              ))}
            </TabsList>


            <TabsContent value="engine" className="mt-0">
              <div className="bg-muted/30 rounded-lg p-4 mb-4">
                <h3 className="font-semibold text-primary mb-3">
                  Engine Specifications
                </h3>
                <div className="space-y-3">
                  <SpecRow
                    label="Engine Type"
                    value={bike.detailed_specs?.engine_type || "N/A"}
                  />
                  <SpecRow
                    label="Displacement"
                    value={currentVariant?.quickSpecs?.engineCapacity || "N/A"}
                  />
                  <SpecRow
                    label="Max Power"
                    value={currentVariant?.quickSpecs?.maxPower || "N/A"}
                  />
                  <SpecRow
                    label="Max Torque"
                    value={currentVariant?.quickSpecs?.maxTorque || "N/A"}
                  />
                  <SpecRow
                    label="Cooling Type"
                    value={currentVariant?.quickSpecs?.coolingType || "N/A"}
                  />
                  <SpecRow
                    label="Spark Plugs"
                    value={currentVariant?.quickSpecs?.sparkPlugs?.toString() || "1"}
                  />
                  <SpecRow
                    label="Fuel System"
                    value={currentVariant?.quickSpecs?.fuelType || "N/A"}
                  />
                  <SpecRow
                    label="Starting"
                    value={bike.detailed_specs?.starting_method || "Electric Start"}
                  />
                </div>
              </div>
              <div className="bg-muted/30 rounded-lg p-4">
                <h3 className="font-semibold text-primary mb-3">Performance</h3>
                <div className="space-y-3">
                  <SpecRow
                    label="Top Speed"
                    value={
                      currentVariant?.quickSpecs?.topspeedCompany ||
                      "130 km/h (Approx.)"
                    }
                  />
                  <SpecRow label="0-60 km/h Acceleration" value="4.2 seconds" />
                  <SpecRow
                    label="Fuel Efficiency"
                    value={currentVariant?.fuelEfficiency || "35-40 kmpl"}
                    badge="City: 35-40 kmpl | Highway: 40-45 kmpl"
                  />
                  <SpecRow
                    label="Fuel Type"
                    value="Petrol (Octane 91 or higher)"
                  />
                  <SpecRow
                    label="Fuel Tank Capacity"
                    value={currentVariant?.quickSpecs?.fuelTank || "12 Liters"}
                  />
                  <SpecRow label="Reserve Fuel Capacity" value="2 Liters" />
                </div>
              </div>
            </TabsContent>

            <TabsContent value="transmission" className="mt-0">
              <div className="bg-muted/30 rounded-lg p-4 mb-4">
                <h3 className="font-semibold text-primary mb-3">
                  Transmission
                </h3>
                <div className="space-y-3">
                  <SpecRow
                    label="Transmission Type"
                    value={currentVariant?.quickSpecs?.transmission || "N/A"}
                  />
                  <SpecRow
                    label="Gear Shift Pattern"
                    value={currentVariant?.quickSpecs?.gearShiftPattern || "N/A"}
                  />
                  <SpecRow
                    label="Clutch"
                    value={bike.detailed_specs?.clutch_type || "Wet Multi-plate"}
                  />
                  <SpecRow
                    label="Final Drive"
                    value={bike.detailed_specs?.final_drive || "Chain Drive"}
                  />
                </div>
              </div>
              <div className="bg-muted/30 rounded-lg p-4">
                <h3 className="font-semibold text-primary mb-3">
                  Brakes & Suspension
                </h3>
                <div className="space-y-3">
                  <SpecRow label="Front Brake" value="Disc - 276mm Petal" />
                  <SpecRow label="Rear Brake" value="Disc - 220mm" />
                  <SpecRow
                    label="Braking System"
                    value={
                      currentVariant?.brakingSystem ||
                      "Dual Channel Disc Brakes"
                    }
                  />
                  <SpecRow
                    label="ABS"
                    value={
                      currentVariant?.abs ? "Dual Channel ABS" : "Not Available"
                    }
                  />
                  <SpecRow label="Front Suspension" value="Inverted Forks" />
                  <SpecRow label="Rear Suspension" value="Monoshock" />
                </div>
              </div>
            </TabsContent>

            <TabsContent value="dimensions" className="mt-0">
              <div className="bg-muted/30 rounded-lg p-4 mb-4">
                <h3 className="font-semibold text-primary mb-3">Dimensions</h3>
                <div className="space-y-3">
                  <SpecRow label="Length" value="2,020 mm" />
                  <SpecRow label="Width" value="756 mm" />
                  <SpecRow label="Height" value="1,055 mm" />
                  <SpecRow label="Wheelbase" value="1,351 mm" />
                  <SpecRow label="Ground Clearance" value="155 mm" />
                  <SpecRow label="Seat Height" value="795 mm" />
                  <SpecRow label="Seat Type" value={currentVariant?.seatType || "Single Seat"} />
                </div>
              </div>
              <div className="bg-muted/30 rounded-lg p-4">
                <h3 className="font-semibold text-primary mb-3">
                  Weight & Tyres
                </h3>
                <div className="space-y-3">
                  <SpecRow
                    label="Kerb Weight"
                    value={currentVariant?.quickSpecs?.kerbWeight || "136 kg"}
                  />
                  <SpecRow
                    label="Front Tyre"
                    value={currentVariant?.frontTire || "110/70-17 Tubeless"}
                  />
                  <SpecRow
                    label="Rear Tyre"
                    value={currentVariant?.rearTire || "150/60-17 Tubeless"}
                  />
                  <SpecRow
                    label="Rear Brake Type"
                    value={currentVariant?.rearBrakeType || "230mm Disc"}
                  />
                  <SpecRow label="Wheel Type" value="Alloy" />
                </div>
              </div>
            </TabsContent>

            <TabsContent value="features" className="mt-0">
              <div className="bg-muted/30 rounded-lg p-4">
                <h3 className="font-semibold text-primary mb-3">
                  Features & Electricals
                </h3>
                <div className="space-y-3">                  <SpecRow
                    label="Headlight Type"
                    value={currentVariant?.projectorHeadlight ? "LED Projector" : "Halogen"}
                    isFeature
                    available={!!currentVariant?.projectorHeadlight || !!currentVariant?.ledHeadlight}
                  />
                  <SpecRow
                    label="DRLs"
                    value={currentVariant?.drls ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.drls}
                  />
                  <SpecRow
                    label="USB Charging Port"
                    value={currentVariant?.usbPort ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.usbPort}
                  />
                  <SpecRow
                    label="Gear Indicator"
                    value={currentVariant?.gearIndicator ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.gearIndicator}
                  />
                  <SpecRow
                    label="Side Stand Cut-off"
                    value={currentVariant?.sideStandCutOff ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.sideStandCutOff}
                  />
                  <SpecRow
                    label="Distance to Empty"
                    value={currentVariant?.distanceToEmpty ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.distanceToEmpty}
                  />
                  <SpecRow
                    label="Avg Fuel Consumption"
                    value={currentVariant?.avgFuelConsumption ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.avgFuelConsumption}
                  />
                  <SpecRow
                    label="Mobile Connectivity"
                    value={currentVariant?.mobileConnectivity ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.mobileConnectivity}
                  />
                  <SpecRow
                    label="GPS & Navigation"
                    value={currentVariant?.gpsNavigation ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.gpsNavigation}
                  />
                  <SpecRow
                    label="Riding Modes"
                    value={currentVariant?.ridingModes ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.ridingModes}
                  />
                  <SpecRow
                    label="Slipper Clutch"
                    value={currentVariant?.slipperClutch ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.slipperClutch}
                  />
                  <SpecRow
                    label="Traction Control"
                    value={currentVariant?.tractionControl ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.tractionControl}
                  />
                  <SpecRow
                    label="Quick Shifter"
                    value={currentVariant?.quickShifter ? "Available" : "Not Available"}
                    isFeature
                    available={!!currentVariant?.quickShifter}
                  />
                  <SpecRow
                    label="Instrument Console"
                    value={currentVariant?.instrumentConsole || "N/A"}
                  />
                  <SpecRow label="Battery" value={bike.detailed_specs?.battery_capacity || "12V, 5Ah MF"} />
                </div>
              </div>
            </TabsContent>
          </Tabs>
        </div>
      </section>

      {/* Pros and Cons Section */}
      {currentVariant?.pros && currentVariant?.cons && (
        <section className="w-full px-4 md:px-8 py-8">
          <div className="bg-card rounded-xl border p-6">
            <h2 className="text-2xl font-bold mb-6">
              Pros and Cons of {bikeName}
            </h2>
            <div className="grid md:grid-cols-2 gap-8">
              {/* Advantages */}
              <div>
                <div className="flex items-center gap-2 mb-4">
                  <Check className="h-5 w-5 text-green-500" />
                  <h3 className="text-lg font-semibold text-green-600">
                    Advantages
