            <Skeleton className="h-5 w-32" />
          </div>
          <Skeleton className="h-24 rounded-xl" />
          <div className="grid grid-cols-3 gap-4">
            <Skeleton className="h-24 rounded-lg" />
            <Skeleton className="h-24 rounded-lg" />
            <Skeleton className="h-24 rounded-lg" />
          </div>
          <Skeleton className="h-32 rounded-xl" />
          <div className="flex gap-3">
