"use client";

import { useAuthStore } from "@/store";
import { useRouter, usePathname } from "next/navigation";
import { useEffect, useState, useRef } from "react";
import { 
  LayoutDashboard, 
  Bike, 
  Heart, 
  Star, 
  Bell, 
  Settings, 
  LogOut,
  ChevronLeft,
  ChevronRight,
  Mail,
  CheckCircle2,
  Loader2,
  PlusCircle,
  User,
  CreditCard
} from "lucide-react";
import Link from "next/link";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";

const navItems = [
  { href: "/dashboard", label: "Overview", icon: LayoutDashboard },
  { href: "/dashboard/my-listings", label: "My Listings", icon: Bike },
  { href: "/dashboard/wishlist", label: "Wishlist (0)", icon: Heart },
  { href: "/dashboard/favorites", label: "Favorites (1)", icon: Star },
  { href: "/dashboard/notifications", label: "Notifications", icon: Bell },
  { href: "/dashboard/my-reviews", label: "My Reviews", icon: Star },
  { href: "/dashboard/subscription", label: "Subscription", icon: CreditCard },
  { href: "/dashboard/shop", label: "My Shop", icon: LayoutDashboard },
  { href: "/dashboard/settings", label: "Settings", icon: Settings },
];

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const { user, logout, isLoading: authLoading } = useAuthStore();
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!authLoading && !user) {
      router.push("/login?callbackUrl=/dashboard");
    }
  }, [user, authLoading, router]);

  const handleLogout = () => {
    logout();
    toast.success("Logged out successfully");
    router.push("/");
  };

  const scroll = (direction: "left" | "right") => {
    if (scrollContainerRef.current) {
      const scrollAmount = 200;
      const newScrollLeft =
        direction === "left"
          ? scrollContainerRef.current.scrollLeft - scrollAmount
          : scrollContainerRef.current.scrollLeft + scrollAmount;

      scrollContainerRef.current.scrollTo({
        left: newScrollLeft,
        behavior: "smooth",
      });
    }
  };

  if (authLoading || !user) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-4">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
        <h2 className="text-xl font-semibold">Loading Dashboard...</h2>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#FDFDFD] dark:bg-[#09090B]">
      <div className="container max-w-6xl py-12 space-y-8 mx-auto">
        {/* Profile Card & Header (Matching Image 3) */}
        <div className="bg-white dark:bg-zinc-900 rounded-3xl p-10 border border-zinc-200 dark:border-zinc-800 shadow-[0_2px_15px_-3px_rgba(0,0,0,0.07),0_4px_6px_-2px_rgba(0,0,0,0.05)] relative overflow-hidden">
          
          <div className="flex flex-col md:flex-row gap-10 items-center justify-between relative z-10">
            <div className="flex flex-col md:flex-row items-center gap-6">
              <div className="h-28 w-28 md:h-32 md:w-32 rounded-full border border-zinc-100 bg-zinc-50 dark:bg-zinc-800 flex items-center justify-center shrink-0">
                <Avatar className="h-full w-full">
                  <AvatarImage src={user.image || undefined} alt={user.name} />
                  <AvatarFallback className="text-3xl bg-zinc-50 text-zinc-300 font-normal">
                    <User className="h-16 w-16" />
                  </AvatarFallback>
                </Avatar>
              </div>
              <div className="space-y-1 text-center md:text-left">
                <p className="text-sm font-medium text-zinc-500 flex items-center justify-center md:justify-start gap-2">
                  <Mail className="h-4 w-4" /> {user.email || "01711111111@mrbikebd.com"}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4 w-full md:w-auto">
              <Button
                variant="outline"
                className="flex-1 md:flex-none h-12 px-6 rounded-xl border-[#FEE2E2] text-rose-500 hover:bg-rose-50 hover:text-rose-600 transition-all font-medium"
                onClick={handleLogout}
              >
                <LogOut className="mr-2 h-4 w-4" /> Logout
              </Button>
              <Button asChild className="flex-1 md:flex-none h-12 px-8 rounded-xl bg-[#F97316] hover:bg-[#EA580C] text-white shadow-sm transition-all font-bold">
                <Link href="/sell-bike">
                  <PlusCircle className="mr-2 h-4 w-4" /> Post Ad
                </Link>
              </Button>
            </div>
          </div>
        </div>

        {/* Horizontal Navigation Tabs (Matching Image 3) */}
        <div className="bg-[#FAF9F6] dark:bg-zinc-900/50 rounded-2xl p-1.5 border border-zinc-100 dark:border-zinc-800">
          <div 
            ref={scrollContainerRef}
            className="flex items-center gap-1 overflow-x-auto scrollbar-hide py-0.5"
          >
            {navItems.map((item) => (
              <Link
                key={item.href}
                href={item.href}
                className={cn(
                  "flex items-center gap-2 px-6 py-3 text-sm font-medium rounded-xl whitespace-nowrap transition-all",
                  pathname === item.href 
                    ? "bg-white dark:bg-zinc-800 text-zinc-900 dark:text-zinc-100 shadow-sm border border-zinc-200/50 dark:border-zinc-700 font-bold" 
                    : "text-zinc-500 hover:text-zinc-900 dark:hover:text-zinc-300"
                )}
              >
                {item.label}
              </Link>
            ))}
          </div>
        </div>

        {/* Content Area */}
        <main className="w-full">
          {children}
        </main>
      </div>
    </div>
  );
}

"use client";

import { useMyListings } from "@/hooks/use-user";
import { 
  Bike, 
  Loader2, 
  PlusCircle, 
  MapPin, 
  Clock, 
  MoreVertical,
  Edit2,
  Trash2,
  ExternalLink
} from "lucide-react";
import { Button } from "@/components/ui/button";
import Link from "next/link";
import Image from "next/image";
import { Badge } from "@/components/ui/badge";
import { 
  DropdownMenu, 
  DropdownMenuContent, 
  DropdownMenuItem, 
  DropdownMenuTrigger 
} from "@/components/ui/dropdown-menu";
import { api } from "@/lib/api-service";
import { API_ENDPOINTS } from "@/config/constants";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { sanitizeImageUrl } from "@/lib/data-utils";

export default function MyListingsPage() {
  const router = useRouter();
  const { data: myListings, isLoading: listingsLoading, refetch } = useMyListings();

  const getStatusColor = (status: string) => {
    switch (status) {
      case "active": return "bg-green-500/10 text-green-600 border-green-200";
      case "pending": return "bg-amber-500/10 text-amber-600 border-amber-200";
      case "rejected": return "bg-rose-500/10 text-rose-600 border-rose-200";
      case "sold": return "bg-blue-500/10 text-blue-600 border-blue-200";
      default: return "bg-gray-500/10 text-gray-600 border-gray-200";
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm("Are you sure you want to delete this listing?")) return;
    
    try {
      const res = await api.delete(API_ENDPOINTS.USED_BIKE_DELETE(String(id)));
      if (res.success) {
        toast.success("Listing deleted successfully");
        refetch();
      } else {
        toast.error(res.error?.message || "Failed to delete listing");
      }
    } catch (err: any) {
      toast.error(err.message || "An error occurred");
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">My Listings</h2>
          <p className="text-muted-foreground">Manage your ads and sales on MrBikeBD.</p>
        </div>
        <Button asChild className="shadow-lg shadow-primary/20 active:scale-95 transition-all">
          <Link href="/sell-bike">
            <PlusCircle className="mr-2 h-4 w-4" /> Post New Ad
          </Link>
        </Button>
      </div>

      {listingsLoading ? (
        <div className="flex flex-col items-center justify-center py-20 space-y-4">
          <Loader2 className="h-10 w-10 animate-spin text-primary/60" />
          <p className="text-muted-foreground animate-pulse">Fetching your listings...</p>
        </div>
      ) : myListings?.length === 0 ? (
        <div className="text-center py-24 border-2 border-dashed rounded-2xl bg-muted/5 space-y-5">
          <div className="h-20 w-20 bg-muted rounded-full flex items-center justify-center mx-auto">
            <Bike className="h-10 w-10 text-muted-foreground/40" />
          </div>
          <div className="space-y-2">
            <h3 className="text-xl font-bold">No ads found</h3>
            <p className="text-muted-foreground">
              You haven't posted any bikes for sale yet.
            </p>
          </div>
          <Button asChild size="lg">
            <Link href="/sell-bike">Start Selling Now</Link>
          </Button>
        </div>
      ) : (
        <div className="grid gap-4">
          {myListings?.map((listing) => (
            <div
              key={listing.id}
              className="group flex flex-col md:flex-row gap-5 p-4 bg-card border rounded-2xl hover:shadow-lg hover:border-primary/20 transition-all duration-300 relative overflow-hidden"
            >
              <div className="h-40 w-full md:w-56 rounded-xl overflow-hidden relative shadow-sm">
                {(() => {
                  const imageUrl = sanitizeImageUrl(
                    listing.image_url || 
                    (listing as any).thumbnail_url || 
                    listing.images?.[0]?.url || 
                    listing.images?.[0], 
                    undefined
                  );
                  return imageUrl ? (
                    <Image
                      src={imageUrl}
                      alt={listing.title}
                      fill
                      className="object-cover transition-transform group-hover:scale-105"
                      unoptimized
                    />
                  ) : (
                    <div className="flex items-center justify-center h-full bg-muted">
                      <Bike className="h-10 w-10 text-muted-foreground/30" />
                    </div>
                  );
                })()}
                <Badge
                  className={`absolute top-3 left-3 px-2 py-0.5 rounded-lg border shadow-sm ${getStatusColor(listing.status)}`}
                >
                  {listing.status.charAt(0).toUpperCase() + listing.status.slice(1)}
                </Badge>
              </div>

              <div className="flex-1 flex flex-col justify-between py-1">
                <div className="space-y-2">
                   <div className="flex justify-between items-start">
                    <h4 className="font-bold text-xl group-hover:text-primary transition-colors line-clamp-1">
                      {listing.title}
                    </h4>
                    <div className="flex items-center gap-1">
                         <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                              <Button variant="ghost" size="icon" className="h-8 w-8 rounded-full hover:bg-muted">
                                <MoreVertical className="h-4 w-4" />
                              </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end" className="w-40 rounded-xl">
                              <DropdownMenuItem onClick={() => router.push(`/sell-bike?edit=${listing.id}`)} className="cursor-pointer">
                                <Edit2 className="mr-2 h-4 w-4" /> Edit
                              </DropdownMenuItem>
                              <DropdownMenuItem className="cursor-pointer">
                                <Link href={`/used-bike/${listing.slug}`} className="flex items-center w-full">
                                    <ExternalLink className="mr-2 h-4 w-4" /> View Ad
                                </Link>
                              </DropdownMenuItem>
                              <DropdownMenuItem 
                                onClick={() => handleDelete(listing.id)}
                                className="text-destructive focus:text-destructive cursor-pointer"
                              >
                                <Trash2 className="mr-2 h-4 w-4" /> Delete
                              </DropdownMenuItem>
                            </DropdownMenuContent>
                          </DropdownMenu>
                    </div>
                  </div>
                  
                  <div className="flex flex-wrap gap-4 text-sm text-muted-foreground">
                    <div className="flex items-center gap-1.5 bg-muted/50 px-2 py-1 rounded-lg">
                      <Clock className="h-3.5 w-3.5" />
                      <span>{new Date(listing.created_at).toLocaleDateString()}</span>
                    </div>
                    <div className="flex items-center gap-1.5 bg-muted/50 px-2 py-1 rounded-lg">
                      <Bike className="h-3.5 w-3.5" />
                      <span>{(listing.mileage || 0).toLocaleString()} km</span>
                    </div>
                    <div className="flex items-center gap-1.5 bg-muted/50 px-2 py-1 rounded-lg">
                      <MapPin className="h-3.5 w-3.5" />
                      <span>{listing.location.full || listing.location.city || "N/A"}</span>
                    </div>
                  </div>
                </div>

                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mt-4 md:mt-0">
                  <div className="space-y-0.5">
                    <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground/60">Asking Price</p>
                    <p className="font-black text-2xl text-primary drop-shadow-sm">
                      ৳ {(Number(listing.price) || 0).toLocaleString()}
                    </p>
                  </div>
                  <div className="flex gap-2 w-full sm:w-auto">
                    <Button 
                      className="flex-1 sm:flex-none active:scale-95 transition-all"
                      variant="outline"
                      asChild
                    >
                        <Link href={`/used-bike/${listing.slug}`}>View Public Ad</Link>
                    </Button>
                    <Button 
                      className="flex-1 sm:flex-none active:scale-95 transition-all"
                      onClick={() => router.push(`/sell-bike?edit=${listing.id}`)}
                    >
                      Quick Edit
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useMyReviews } from "@/hooks/use-user";
import { useUpdateReview, useDeleteReview } from "@/hooks/use-bikes";
import { 
  Star, 
  Loader2, 
  MessageSquare, 
  MoreVertical,
  Edit2,
  Trash2,
  Bike,
  ExternalLink,
  CheckCircle2,
  Clock
} from "lucide-react";
import { Button } from "@/components/ui/button";
import Link from "next/link";
import { Badge } from "@/components/ui/badge";
import { 
  DropdownMenu, 
  DropdownMenuContent, 
  DropdownMenuItem, 
  DropdownMenuTrigger 
} from "@/components/ui/dropdown-menu";
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogFooter,
  DialogDescription
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { useState } from "react";
import { cn } from "@/lib/utils";
import { Review } from "@/types";

export default function MyReviewsPage() {
  const { data: myReviews, isLoading: reviewsLoading } = useMyReviews();
  const { mutate: updateReview, isPending: updatePending } = useUpdateReview();
  const { mutate: deleteReview } = useDeleteReview();

  const [editingReview, setEditingReview] = useState<Review | null>(null);
  const [editRating, setEditRating] = useState(0);
  const [editComment, setEditComment] = useState("");

  const handleEditClick = (review: Review) => {
    setEditingReview(review);
    setEditRating(review.rating);
    setEditComment(review.comment);
  };

  const handleUpdate = () => {
    if (!editingReview) return;
    updateReview(
      { 
        reviewId: String(editingReview.id), 
        rating: editRating, 
        comment: editComment 
      },
      {
        onSuccess: () => {
          toast.success("Review updated successfully");
          setEditingReview(null);
        },
        onError: (err: any) => {
          toast.error(err.message || "Failed to update review");
        }
      }
    );
  };

  const handleDeleteClick = (review: Review) => {
    if (!confirm("Are you sure you want to delete this review?")) return;
    deleteReview(
      { reviewId: String(review.id), bikeId: review.bikeId },
      {
        onSuccess: () => toast.success("Review deleted successfully"),
        onError: (err: any) => toast.error(err.message || "Failed to delete review")
      }
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">My Reviews</h2>
          <p className="text-muted-foreground">Manage your bike reviews and ratings.</p>
        </div>
      </div>

      {reviewsLoading ? (
        <div className="flex flex-col items-center justify-center py-20 space-y-4">
          <Loader2 className="h-10 w-10 animate-spin text-primary/60" />
          <p className="text-muted-foreground animate-pulse">Fetching your reviews...</p>
        </div>
      ) : myReviews?.length === 0 ? (
        <div className="text-center py-24 border-2 border-dashed rounded-2xl bg-muted/5 space-y-5">
          <div className="h-20 w-20 bg-muted rounded-full flex items-center justify-center mx-auto">
            <MessageSquare className="h-10 w-10 text-muted-foreground/40" />
          </div>
          <div className="space-y-2">
            <h3 className="text-xl font-bold">No reviews found</h3>
            <p className="text-muted-foreground">
              You haven't reviewed any bikes yet.
            </p>
          </div>
          <Button asChild size="lg">
            <Link href="/bikes">Explore Bikes to Review</Link>
          </Button>
        </div>
      ) : (
        <div className="grid gap-4">
          {myReviews?.map((review: Review) => (
            <div
              key={review.id}
              className="group flex flex-col p-6 bg-card border rounded-2xl hover:shadow-lg hover:border-primary/20 transition-all duration-300 relative overflow-hidden"
            >
              <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-4">
                  <div className="h-12 w-12 rounded-xl bg-primary/5 flex items-center justify-center text-primary border border-primary/10">
                    <Bike className="h-6 w-6" />
                  </div>
                  <div>
                    <h4 className="font-bold text-lg group-hover:text-primary transition-colors">
                      {review.bike_name || "Unknown Bike"}
                    </h4>
                    <div className="flex items-center gap-2 mt-0.5">
                      <div className="flex">
                        {[1, 2, 3, 4, 5].map((star) => (
                          <Star
                            key={star}
                            className={cn(
                              "h-3.5 w-3.5",
                              star <= review.rating
                                ? "fill-yellow-400 text-yellow-400"
                                : "text-muted-foreground/20"
                            )}
                          />
                        ))}
                      </div>
                      <span className="text-xs text-muted-foreground">
                        {review.rating.toFixed(1)} / 5.0
                      </span>
                    </div>
                  </div>
                </div>
                
                <div className="flex items-center gap-2">
                  {review.isVerifiedOwner && (
                    <Badge variant="secondary" className="bg-green-500/10 text-green-600 border-green-200 gap-1 hidden sm:flex">
                      <CheckCircle2 className="h-3 w-3" /> Verified Owner
                    </Badge>
                  )}
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon" className="h-8 w-8 rounded-full hover:bg-muted">
                        <MoreVertical className="h-4 w-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="w-40 rounded-xl">
                      <DropdownMenuItem onClick={() => handleEditClick(review)} className="cursor-pointer">
                        <Edit2 className="mr-2 h-4 w-4" /> Edit
                      </DropdownMenuItem>
                      <DropdownMenuItem className="cursor-pointer" asChild>
                        <Link href={`/bike/${review.bike_slug}`}>
                          <ExternalLink className="mr-2 h-4 w-4" /> View Bike
                        </Link>
                      </DropdownMenuItem>
                      <DropdownMenuItem 
                        onClick={() => handleDeleteClick(review)}
                        className="text-destructive focus:text-destructive cursor-pointer"
                      >
                        <Trash2 className="mr-2 h-4 w-4" /> Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              </div>

              <div className="bg-muted/30 rounded-xl p-4 border border-zinc-100 dark:border-zinc-800">
                <p className="text-sm text-zinc-600 dark:text-zinc-400 italic">
                  &quot;{review.comment}&quot;
                </p>
              </div>

              <div className="flex items-center gap-4 mt-4 text-xs text-muted-foreground">
                <div className="flex items-center gap-1.5">
                  <Clock className="h-3.5 w-3.5" />
                  <span>
                    {(review.created_at || review.createdAt) ? 
                      new Date(review.created_at || review.createdAt!).toLocaleDateString() : 
                      "N/A"}
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Edit Review Dialog */}
      <Dialog open={!!editingReview} onOpenChange={(open) => !open && setEditingReview(null)}>
        <DialogContent className="sm:max-w-[500px] rounded-3xl">
          <DialogHeader>
            <DialogTitle className="text-2xl font-bold">Edit Review</DialogTitle>
            <DialogDescription>
              Update your rating and feedback for {editingReview?.bike_name}.
            </DialogDescription>
          </DialogHeader>
          
          <div className="space-y-6 py-4">
            <div className="space-y-2">
              <label className="text-sm font-semibold">Your Rating</label>
              <div className="flex gap-2">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    type="button"
                    onClick={() => setEditRating(star)}
                    className="focus:outline-none transition-transform hover:scale-110"
                  >
                    <Star
                      className={cn(
                        "h-8 w-8 transition-colors",
                        star <= editRating
                          ? "fill-yellow-400 text-yellow-400"
                          : "text-muted-foreground/20"
                      )}
                    />
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-semibold">Your Opinion</label>
              <Textarea
                placeholder="Share your updated experience..."
                value={editComment}
                onChange={(e) => setEditComment(e.target.value)}
                rows={5}
                className="rounded-2xl resize-none focus-visible:ring-primary/20"
              />
            </div>
          </div>

          <DialogFooter className="gap-2 sm:gap-0">
            <Button 
              variant="outline" 
              onClick={() => setEditingReview(null)}
              className="rounded-xl px-6"
            >
              Cancel
            </Button>
            <Button 
              onClick={handleUpdate}
              disabled={updatePending || editRating === 0}
              className="rounded-xl px-8 bg-[#F97316] hover:bg-[#EA580C]"
            >
              {updatePending ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Updating...
                </>
              ) : (
                "Save Changes"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useNotifications } from "@/hooks/use-user";
import { 
  Bell, 
  Loader2, 
  CheckCircle2, 
  Mail,
  Trash2,
  MoreHorizontal
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { 
  DropdownMenu, 
  DropdownMenuContent, 
  DropdownMenuItem, 
  DropdownMenuTrigger 
} from "@/components/ui/dropdown-menu";

interface Notification {
  title: string;
  message: string;
  read: boolean;
  created_at: string;
  [key: string]: unknown;
}

export default function NotificationsPage() {
  const { data: notificationsData, isLoading: notificationsLoading } = useNotifications();

  const notifications = Array.isArray(notificationsData)
    ? notificationsData
    : (notificationsData as unknown as { results: Notification[] })?.results || [];

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Notifications</h2>
          <p className="text-muted-foreground">Stay updated with your site activity.</p>
        </div>
        <Button variant="outline" size="sm" className="hidden sm:flex rounded-xl">
          Mark all as read
        </Button>
      </div>

      {notificationsLoading ? (
        <div className="flex flex-col items-center justify-center py-20">
          <Loader2 className="h-10 w-10 animate-spin text-primary/60" />
        </div>
      ) : !notifications || notifications.length === 0 ? (
        <div className="text-center py-24 border-2 border-dashed rounded-2xl bg-muted/5 space-y-4">
          <div className="h-16 w-16 bg-muted rounded-full flex items-center justify-center mx-auto">
            <Bell className="h-8 w-8 text-muted-foreground/40" />
          </div>
          <h3 className="text-lg font-semibold">All caught up!</h3>
          <p className="text-muted-foreground">No new notifications to show.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {notifications.map((notification: Notification, i: number) => (
            <Card key={i} className={cn(
              "border-none shadow-sm hover:shadow-md transition-all duration-300 relative overflow-hidden group",
              notification.read ? "bg-card" : "bg-primary/[0.02] border-l-4 border-l-primary"
            )}>
              <CardContent className="p-4 flex gap-4 items-start">
                <div className={cn(
                  "h-10 w-10 rounded-xl flex items-center justify-center shrink-0",
                  notification.read ? "bg-muted" : "bg-primary/10"
                )}>
                  <CheckCircle2 className={cn("h-5 w-5", notification.read ? "text-muted-foreground" : "text-primary")} />
                </div>
                <div className="flex-1 min-w-0 space-y-1">
                  <div className="flex justify-between items-start gap-2">
                    <p className="font-bold truncate text-sm sm:text-base">
                      {notification.title || "System Message"}
                    </p>
                    <span className="text-[10px] sm:text-xs text-muted-foreground whitespace-nowrap">
                       {new Date(notification.created_at).toLocaleDateString()}
                    </span>
                  </div>
                  <p className="text-xs sm:text-sm text-muted-foreground leading-relaxed">
                    {notification.message || "You have a new update."}
                  </p>
                </div>
                <DropdownMenu>
                   <DropdownMenuTrigger asChild>
                     <Button variant="ghost" size="icon" className="h-8 w-8 rounded-full opacity-0 group-hover:opacity-100 transition-opacity">
                        <MoreHorizontal className="h-4 w-4" />
                     </Button>
                   </DropdownMenuTrigger>
                   <DropdownMenuContent align="end" className="rounded-xl">
                      <DropdownMenuItem className="cursor-pointer">Mark as read</DropdownMenuItem>
                      <DropdownMenuItem className="text-destructive focus:text-destructive cursor-pointer">
                        <Trash2 className="mr-2 h-4 w-4" /> Delete
                      </DropdownMenuItem>
                   </DropdownMenuContent>
                </DropdownMenu>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

