function LoginContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const callbackUrl = searchParams.get("callbackUrl") || "/";
  const [isLoading, setIsLoading] = useState(false);

  // Email login states
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [verificationError, setVerificationError] = useState(false);

  // 2FA states (for admin users)
  const [requires2FA, setRequires2FA] = useState(false);
  const [totpSession, setTotpSession] = useState("");
  const [totpCode, setTotpCode] = useState("");


  const handleGoogleLogin = () => {
    setIsLoading(true);
    signIn("google", { callbackUrl });
  };

  const handleEmailLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) {
      toast.error("Please enter your email address");
      return;
    }
    if (!password) {
      toast.error("Please enter your password");
      return;
    }

    setIsLoading(true);
    setVerificationError(false);
    try {
      // First call to backend to check password and get 2FA status
      const response = await fetch(
        `${process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api/v1"}/users/auth/login/`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email, password }),
        }
      );
      const data = await response.json();

      if (!response.ok) {
        if (data.needs_verification) {
          setVerificationError(true);
          toast.error("Email not verified", {
            description: "Please check your inbox or resend the verification link.",
          });
        } else {
          toast.error(data.error || "Invalid email or password");
        }
        return;
      }

      // Backend returned 2FA requirement
      if (data.requires_2fa) {
        setTotpSession(data.totp_session);
        setRequires2FA(true);
        toast.info("Verification code sent", {
          description: "Please check your registered email for the 6-digit login code.",
        });
        return;
      }

      // No 2FA — proceed with NextAuth sign in
      const result = await signIn("email-password", {
        email,
        password,
        redirect: false,
        callbackUrl,
      });

      if (result?.error) {
        toast.error(result.error || "Invalid email or password");
      } else {
        toast.success("Successfully logged in!");
        router.push(callbackUrl);
        router.refresh();
      }
    } catch (error: any) {
      console.error("Email login error:", error);
      toast.error(error.message || "An error occurred during sign in");
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerify2FA = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!totpCode || totpCode.length !== 6) {
      toast.error("Please enter a 6-digit code");
      return;
    }

    setIsLoading(true);
    try {
      // Normal 2FA Verification during login
      const result = await signIn("verify-2fa", {
        totp_session: totpSession,
        code: totpCode,
        redirect: false,
        callbackUrl,
      });

      if (result?.error) {
        toast.error(result.error || "Invalid code. Please try again.");
        setTotpCode("");
      } else {
        toast.success("Successfully logged in!");
        router.push(callbackUrl);
        router.refresh();
      }
    } catch (error: any) {
      toast.error("Network error. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendVerification = async () => {
    if (!email) {
      toast.error("Please enter your email address first");
      return;
    }

    setIsLoading(true);
    try {
      const response = await fetch(`${process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api/v1"}/users/auth/resend-verification/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });
      const data = await response.json();

      if (response.ok) {
        toast.success("Verification email sent!");
        setVerificationError(false);
      } else {
        toast.error(data.error || "Failed to resend verification link");
      }
    } catch (error) {
      toast.error("Network error. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <div className="md:hidden flex flex-col items-center mb-8">
        <div className="bg-primary/10 w-16 h-16 rounded-2xl flex items-center justify-center mb-4">
          <Image
            src="/images/onlybike_dark.png"
            alt="MrBikeBD"
            width={40}
            height={40}
            className="object-contain"
          />
        </div>
        <Image
          src="/images/onlytext_dark.png"
          alt="MrBikeBD"
          width={120}
          height={40}
          className="h-12 w-auto object-contain"
        />
      </div>

      <AnimatePresence mode="wait">
        {/* ── STEP 1: Email + Password ── */}
        {!requires2FA && (
          <motion.div
            key="email-step"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            transition={{ duration: 0.3 }}
          >
            <div className="space-y-2 mb-6">
              <h1 className="text-3xl font-bold tracking-tight">Welcome Back</h1>
              <p className="text-muted-foreground">Sign in with your email and password</p>
            </div>

            <form onSubmit={handleEmailLogin} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="email">Email Address</Label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="email"
                    type="email"
                    placeholder="name@example.com"
                    className="pl-10 h-12 text-lg"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                  />
                </div>
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label htmlFor="password">Password</Label>
                  <Link
                    href="/forgot-password"
                    className="text-sm text-primary hover:underline font-medium"
                  >
                    Forgot password?
                  </Link>
                </div>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="password"
                    type={showPassword ? "text" : "password"}
                    placeholder="Enter your password"
                    className="pl-10 pr-10 h-12 text-lg"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                    aria-label={showPassword ? "Hide password" : "Show password"}
                  >
                    {showPassword ? (
                      <EyeOff className="h-4 w-4" />
                    ) : (
                      <Eye className="h-4 w-4" />
                    )}
                  </button>
                </div>
              </div>

              {verificationError && (
                <div className="bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-700 flex flex-col gap-2">
                  <p>Your email has not been verified yet.</p>
                  <Button
                    variant="link"
                    className="p-0 text-red-700 font-bold justify-start h-auto"
                    onClick={handleResendVerification}
                    disabled={isLoading}
                    type="button"
                  >
                    Resend verification link
                  </Button>
                </div>
              )}

              <Button
                type="submit"
                className="w-full h-12 text-lg font-semibold"
                disabled={isLoading}
              >
                {isLoading ? (
                  <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                ) : (
                  <>
                    Sign In
                    <ArrowRight className="ml-2 h-5 w-5" />
                  </>
                )}
              </Button>
            </form>

            <div className="mt-8 space-y-6">
              <div className="relative">
                <div className="absolute inset-0 flex items-center">
                  <span className="w-full border-t border-zinc-200" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-transparent px-4 text-muted-foreground font-medium">
                    Or continue with
                  </span>
                </div>
              </div>

              <Button
                variant="outline"
                className="w-full h-12 text-base font-medium border-zinc-200 hover:bg-zinc-50"
                onClick={handleGoogleLogin}
                disabled={isLoading}
              >
                <Chrome className="mr-2 h-5 w-5 text-red-500" />
                Sign in with Google
              </Button>
            </div>

            <p className="mt-10 text-center text-sm text-muted-foreground">
              Don&apos;t have an account?{" "}
              <Link
                href="/register"
                className="text-primary hover:underline font-semibold"
              >
                Sign up
              </Link>
            </p>

            <p className="mt-6 text-center text-xs text-muted-foreground">
              By continuing, you agree to our{" "}
              <a href="/terms" className="underline underline-offset-4 hover:text-primary">
                Terms of Service
              </a>{" "}
              and{" "}
              <a href="/privacy" className="underline underline-offset-4 hover:text-primary">
                Privacy Policy
              </a>
              .
            </p>
          </motion.div>
        )}

        {/* ── STEP 2: 2FA TOTP Code ── */}
        {requires2FA && (
          <motion.div
            key="totp-step"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            transition={{ duration: 0.3 }}
          >
            <div className="flex flex-col items-center mb-8 text-center">
              <div className="bg-primary/10 w-16 h-16 rounded-2xl flex items-center justify-center mb-4">
                <ShieldCheck className="h-8 w-8 text-primary" />
              </div>
              <h1 className="text-2xl font-bold tracking-tight">Email Verification</h1>
              <p className="text-muted-foreground mt-2 max-w-xs">
                We've sent a 6-digit login code to your registered email address.
              </p>
            </div>

            <form onSubmit={handleVerify2FA} className="space-y-5">
              <div className="space-y-2">
                <Label htmlFor="totp-code">Verification Code</Label>
                <div className="relative">
                  <KeyRound className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="totp-code"
                    type="text"
                    inputMode="numeric"
                    pattern="[0-9]{6}"
                    maxLength={6}
                    placeholder="000000"
                    className="pl-10 h-14 text-2xl tracking-[0.5em] text-center font-mono"
                    value={totpCode}
                    onChange={(e) => setTotpCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
                    autoFocus
                    autoComplete="one-time-code"
                    required
                  />
                </div>
              </div>

              <Button
                type="submit"
                className="w-full h-12 text-lg font-semibold"
                disabled={isLoading || totpCode.length !== 6}
              >
                {isLoading ? (
                  <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                ) : (
                  <>
                    Verify & Sign In
                    <ShieldCheck className="ml-2 h-5 w-5" />
                  </>
                )}
              </Button>

              <Button
                type="button"
                variant="ghost"
                className="w-full"
                onClick={() => {
                  setRequires2FA(false);
                  setTotpCode("");
                  setTotpSession("");
                }}
                disabled={isLoading}
              >
                ← Back to login
              </Button>
            </form>

            <p className="mt-6 text-center text-xs text-muted-foreground">
              Lost access to your authenticator?{" "}
              <a href="mailto:contact@mrbikebd.com" className="text-primary hover:underline">
                Contact support
              </a>
            </p>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

"use client";

import Link from "next/link";
import Image from "next/image";
import {
  Clock,
  Calendar,
  Share2,
  ChevronRight,
  Facebook,
  Twitter,
  Linkedin,
  Hash,
  ArrowLeft,
  ImageOff,
} from "lucide-react";
import { useNewsArticle } from "@/hooks/use-news";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";

interface NewsDetailClientProps {
  slug: string;
  initialData?: any;
}

export function NewsDetailClient({ slug, initialData }: NewsDetailClientProps) {
  const { data: article, isLoading } = useNewsArticle(slug, initialData);

  if (isLoading) {
    return <LoadingState />;
  }

  if (!article) {
    return <NotFoundState />;
  }

  const authorName =
    article.author?.username ||
    [article.author?.first_name, article.author?.last_name].filter(Boolean).join(" ") ||
    "Unknown Author";
  const authorImage = (article.author as any)?.profile_image || undefined;

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: article.title,
        url: window.location.href,
      });
    }
  };

  return (
    <article className="min-h-screen pb-20">
      {/* Breadcrumb / Back Navigation */}
      <div className="bg-muted/30 border-b sticky top-[64px] z-10 backdrop-blur-md bg-background/80 hidden md:block">
        <div className="w-full px-4 md:px-8 py-3 max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2 text-sm text-muted-foreground overflow-hidden">
            <Link
              href="/news"
              className="hover:text-foreground flex items-center transition-colors"
            >
              <ArrowLeft className="mr-1 h-4 w-4" /> Back to News
            </Link>
            <ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground/50" />
            <span className="text-foreground font-medium truncate max-w-[200px] sm:max-w-md">
              {article.title}
            </span>
          </div>
          <Button variant="ghost" size="icon" onClick={handleShare}>
            <Share2 className="h-4 w-4" />
          </Button>
        </div>
      </div>

      <div className="w-full px-4 md:px-8 max-w-6xl mx-auto py-8 md:py-12 space-y-8">
        {/* Article Header */}
        <header className="space-y-6">
          <div className="flex items-center gap-3 flex-wrap">
            <Badge className="capitalize px-3 py-1 text-base">
              {article.category}
            </Badge>
            <span className="text-muted-foreground flex items-center gap-1.5 text-sm font-medium">
              <Calendar className="h-4 w-4" />
              {new Date(article.published_at).toLocaleDateString("en-US", {
                month: "long",
                day: "numeric",
                year: "numeric",
              })}
            </span>
            <span className="text-muted-foreground flex items-center gap-1.5 text-sm font-medium ml-auto sm:ml-0">
              <Clock className="h-4 w-4" />5 min read
            </span>
          </div>

          <h1 className="text-3xl md:text-5xl font-extrabold leading-tight tracking-tight text-foreground">
            {article.title}
          </h1>

          <div className="flex items-center justify-between py-4 border-y">
            <div className="flex items-center gap-3">
              <Avatar className="h-10 w-10 border">
                <AvatarImage src={authorImage} alt={authorName} />
                <AvatarFallback>{authorName.charAt(0)}</AvatarFallback>
              </Avatar>
              <div>
                <p className="text-sm font-bold">
                  {authorName}
                </p>
                <p className="text-xs text-muted-foreground">Author</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <a
                href="#"
                className="p-2 rounded-full bg-muted/50 hover:bg-blue-100 hover:text-blue-600 transition-colors"
              >
                <Facebook className="h-4 w-4" />
              </a>
              <a
                href="#"
                className="p-2 rounded-full bg-muted/50 hover:bg-sky-100 hover:text-sky-500 transition-colors"
              >
                <Twitter className="h-4 w-4" />
              </a>
              <a
                href="#"
                className="p-2 rounded-full bg-muted/50 hover:bg-blue-100 hover:text-blue-700 transition-colors"
              >
                <Linkedin className="h-4 w-4" />
              </a>
            </div>
          </div>
        </header>

        {/* Featured Image */}
        {article.featured_image ? (
          <div className="aspect-[16/9] relative rounded-2xl overflow-hidden shadow-sm">
            <Image
              src={article.featured_image}
              alt={article.title}
              fill
              className="object-cover"
              priority
            />
          </div>
        ) : (
          <div className="aspect-[16/9] relative rounded-2xl overflow-hidden shadow-sm bg-muted flex items-center justify-center">
            <div className="text-muted-foreground flex flex-col items-center gap-2">
              <ImageOff className="h-12 w-12 opacity-20" />
              <span className="text-sm opacity-50">No featured image</span>
            </div>
          </div>
        )}

        {/* Content */}
        <div
          className="prose prose-zinc dark:prose-invert max-w-none 
                    first-letter:text-5xl first-letter:font-bold first-letter:mr-3 first-letter:float-left
                    [&>p]:text-lg [&>p]:leading-relaxed [&>p]:text-muted-foreground/90 [&>p]:mb-6
                    [&>h3]:text-2xl [&>h3]:font-bold [&>h3]:mt-10 [&>h3]:mb-4 [&>h3]:text-foreground
                    [&>ul]:list-disc [&>ul]:pl-6 [&>ul]:mb-6 [&>li]:mb-2"
          dangerouslySetInnerHTML={{ __html: article.content }}
        />

        <Separator className="my-8" />

        {/* Footer / Tags */}
        <div className="space-y-6">
          <div className="flex flex-wrap gap-2">
            {(article.tags || []).map((tag: any) => {
              const tagLabel = typeof tag === "string" ? tag : tag.name || String(tag.id || "tag");
              const key = typeof tag === "string" ? tag : tag.id || tag.name || JSON.stringify(tag);
              return (
                <Badge
                  key={key}
                  variant="secondary"
                  className="px-3 py-1 bg-muted hover:bg-muted/80 text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
                >
                  <Hash className="h-3 w-3 mr-1" />
                  {tagLabel}
                </Badge>
              );
            })}
          </div>

          <div className="bg-muted/30 rounded-xl p-8 text-center space-y-4">
            <h3 className="text-xl font-bold">Enjoyed this article?</h3>
            <p className="text-muted-foreground max-w-md mx-auto">
              Subscribe to our newsletter to get the latest bike news and
              reviews delivered straight to your inbox.
            </p>
            <div className="flex gap-2 max-w-xs mx-auto">
              <Button className="w-full">Subscribe Newsletter</Button>
            </div>
          </div>
        </div>
      </div>
    </article>
  );
}

function LoadingState() {
  return (
    <div className="w-full px-4 md:px-8 max-w-6xl mx-auto py-12 space-y-8">
      <div className="h-8 w-32 bg-muted rounded" />
      <div className="h-16 w-3/4 bg-muted rounded" />
      <div className="flex gap-4">
        <div className="h-10 w-10 rounded-full bg-muted" />
        <div className="h-10 w-32 bg-muted rounded" />
      </div>
      <div className="aspect-video w-full bg-muted rounded-2xl" />
      <div className="space-y-4">
        <div className="h-4 w-full bg-muted rounded" />
        <div className="h-4 w-full bg-muted rounded" />
        <div className="h-4 w-2/3 bg-muted rounded" />
      </div>
    </div>
  );
}

function NotFoundState() {
  return (
    <div className="min-h-[60vh] flex flex-col items-center justify-center p-4 text-center">
      <h1 className="text-3xl font-bold mb-4">Article Not Found</h1>
      <p className="text-muted-foreground mb-8 text-lg">
        The article you are looking for does not exist or has been removed.
      </p>
      <Button asChild size="lg">
        <Link href="/news">Browse All News</Link>
      </Button>
    </div>
  );
}

