function RegisterContent() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [formData, setFormData] = useState({
    username: "",
    email: "",
    password: "",
    confirmPassword: "",
    first_name: "",
    last_name: "",
  });
  const [isRegistered, setIsRegistered] = useState(false);
  const [isResendingEmail, setIsResendingEmail] = useState(false);
  const [resendCooldown, setResendCooldown] = useState(0);

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.id]: e.target.value });
  };

  const handleRegister = async (e: FormEvent) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      toast.error("Passwords do not match");
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch(
        `${process.env.NEXT_PUBLIC_API_URL}/users/auth/register/`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            username: formData.username,
            email: formData.email,
            password: formData.password,
            first_name: formData.first_name,
            last_name: formData.last_name,
          }),
        },
      );

      const data = await res.json();

      if (res.ok) {
        setIsRegistered(true);
        toast.success("Account created! Check your email for the verification link.");
      } else {
        // Handle both flat errors and StandardResponse format
        const errorMsg =
          data?.error?.message ||
          data?.detail ||
          (data?.email ? (Array.isArray(data.email) ? data.email[0] : data.email) : null) ||
          (data?.username ? (Array.isArray(data.username) ? data.username[0] : data.username) : null) ||
          (data?.password ? (Array.isArray(data.password) ? data.password[0] : data.password) : null) ||
          "Registration failed. Please try again.";
        toast.error(errorMsg);
      }
    } catch (error: unknown) {
      console.error("Registration error:", error);
      toast.error("Network error. Please check your connection and try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendEmail = async () => {
    if (resendCooldown > 0) return;
    setIsResendingEmail(true);
    try {
      const res = await fetch(
        `${process.env.NEXT_PUBLIC_API_URL}/users/auth/resend-verification/`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email: formData.email }),
        }
      );
      if (res.ok) {
        toast.success("Verification email resent! Check your inbox.");
        setResendCooldown(60);
        const interval = setInterval(() => {
          setResendCooldown((c) => {
            if (c <= 1) { clearInterval(interval); return 0; }
            return c - 1;
          });
        }, 1000);
      } else {
        toast.error("Failed to resend. Please try again.");
      }
    } catch {
      toast.error("Network error.");
    } finally {
      setIsResendingEmail(false);
    }
  };

  const handleGoogleLogin = () => {
    signIn("google", { callbackUrl: "/profile" });
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <div className="md:hidden flex flex-col items-center mb-8">
        <div className="bg-primary/10 w-16 h-16 rounded-2xl flex items-center justify-center mb-4">
          <Image
            src="/images/onlybike_dark.png"
            alt="MrBikeBD"
            width={40}
            height={40}
            className="object-contain"
          />
        </div>
        <Image
          src="/images/onlytext_dark.png"
          alt="MrBikeBD"
          width={120}
          height={40}
          className="h-12 w-auto object-contain"
        />
      </div>

      <div className="space-y-2 mb-8">
        <h1 className="text-3xl font-bold tracking-tight">Create Account</h1>
        <p className="text-muted-foreground">
          Join Bangladesh&apos;s #1 Motorcycle Ecosystem
        </p>
      </div>

      <AnimatePresence mode="wait">
        {isRegistered ? (
          <motion.div
            key="success-view"
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-primary/5 rounded-2xl p-8 border border-primary/20 text-center space-y-6"
          >
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ type: "spring", stiffness: 200, damping: 12 }}
              className="bg-primary/10 w-20 h-20 rounded-full flex items-center justify-center mx-auto text-primary"
            >
              <Mail className="h-10 w-10" />
            </motion.div>
            <div className="space-y-2">
              <h2 className="text-2xl font-bold">Check your inbox!</h2>
              <p className="text-muted-foreground">
                We&apos;ve sent a verification link to{" "}
                <span className="text-foreground font-semibold">{formData.email}</span>.
              </p>
            </div>
            <div className="bg-background rounded-xl p-4 text-sm text-left space-y-2 border border-border">
              <p className="font-semibold text-foreground">📋 Next steps:</p>
              <ol className="list-decimal list-inside space-y-1 text-muted-foreground">
                <li>Open your email inbox</li>
                <li>Click <strong>Verify My Email</strong> in the email</li>
                <li>You&apos;ll be automatically logged in</li>
              </ol>
              <p className="text-xs text-muted-foreground mt-2">The link expires in <strong>24 hours</strong>. Check your spam folder if you don&apos;t see it.</p>
            </div>
            <div className="flex flex-col gap-3 pt-2">
              <Link href="/login" passHref>
                <Button className="w-full h-12 text-base font-semibold">
                  Back to Login
                </Button>
              </Link>
              <Button
                variant="ghost"
                className="w-full h-12 text-sm"
                onClick={handleResendEmail}
                disabled={isResendingEmail || resendCooldown > 0}
              >
                {isResendingEmail ? (
                  <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Sending...</>
                ) : resendCooldown > 0 ? (
                  `Resend in ${resendCooldown}s`
                ) : (
                  `Didn't receive it? Resend email`
                )}
              </Button>
            </div>
          </motion.div>

        ) : (
          <motion.div key="form-view">
            <form onSubmit={handleRegister} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="first_name">First Name</Label>
                  <Input
                    id="first_name"
                    placeholder="John"
                    className="h-11"
                    value={formData.first_name}
                    onChange={handleChange}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="last_name">Last Name</Label>
                  <Input
                    id="last_name"
                    placeholder="Doe"
                    className="h-11"
                    value={formData.last_name}
                    onChange={handleChange}
                    required
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="username">Username</Label>
                <Input
                  id="username"
                  placeholder="johndoe123"
                  className="h-11"
                  value={formData.username}
                  onChange={handleChange}
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="email">Email Address</Label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="email"
                    type="email"
                    placeholder="name@example.com"
                    className="pl-10 h-11"
                    value={formData.email}
                    onChange={handleChange}
                    required
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="password">Password</Label>
                  <div className="relative">
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                      id="password"
                      type={showPassword ? "text" : "password"}
                      className="pl-10 pr-10 h-11"
                      value={formData.password}
                      onChange={handleChange}
                      required
                    />
                    <button
                      type="button"
                      className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground hover:text-primary transition-colors"
                      onClick={() => setShowPassword(!showPassword)}
                    >
                      {showPassword ? (
                        <EyeOff className="h-4 w-4" />
                      ) : (
                        <Eye className="h-4 w-4" />
                      )}
                    </button>
                  </div>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="confirmPassword">Confirm</Label>
                  <div className="relative">
                    <Input
                      id="confirmPassword"
                      type={showConfirmPassword ? "text" : "password"}
                      className="pr-10 h-11"
                      value={formData.confirmPassword}
                      onChange={handleChange}
                      required
                    />
                    <button
                      type="button"
                      className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground hover:text-primary transition-colors"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    >
                      {showConfirmPassword ? (
                        <EyeOff className="h-4 w-4" />
                      ) : (
                        <Eye className="h-4 w-4" />
                      )}
                    </button>
                  </div>
                </div>
              </div>

              <Button
                type="submit"
                className="w-full h-12 text-lg font-semibold mt-2"
                disabled={isLoading}
              >
                {isLoading ? (
                  <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                ) : (
                  <>
                    Create Account
                    <ArrowRight className="ml-2 h-5 w-5" />
                  </>
                )}
              </Button>
            </form>

            <div className="mt-8 space-y-6">
              <div className="relative">
                <div className="absolute inset-0 flex items-center">
                  <span className="w-full border-t border-zinc-200" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-transparent px-4 text-muted-foreground font-medium">
                    Or continue with
                  </span>
                </div>
              </div>

              <Button
                variant="outline"
                className="w-full h-12 text-base font-medium border-zinc-200 hover:bg-zinc-50"
                onClick={handleGoogleLogin}
                disabled={isLoading}
              >
                <Chrome className="mr-2 h-5 w-5 text-red-500" />
                Sign up with Google
              </Button>
            </div>

            <p className="mt-8 text-center text-sm text-muted-foreground">
              Already have an account?{" "}
              <Link
                href="/login"
                className="text-primary hover:underline font-semibold"
              >
                Log in
              </Link>
            </p>

            <p className="mt-6 text-center text-xs text-muted-foreground leading-relaxed">
              By creating an account, you agree to our{" "}
              <Link
                href="/terms"
                className="underline underline-offset-4 hover:text-primary"
              >
                Terms of Service
              </Link>{" "}
              and{" "}
              <Link
                href="/privacy"
                className="underline underline-offset-4 hover:text-primary"
              >
                Privacy Policy
              </Link>
              .
            </p>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
  Flag,
  ChevronRight,
  Loader2,
  CheckCircle2,
  AlertTriangle,
  MessageSquareWarning,
  Copy,
  ShieldAlert,
  HelpCircle,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { motion } from "framer-motion";
import { use } from "react";

const REPORT_REASONS = [
  { value: "fraud", label: "Fraud / Scam", icon: ShieldAlert },
  { value: "spam", label: "Spam", icon: AlertTriangle },
  { value: "duplicate", label: "Duplicate Listing", icon: Copy },
  { value: "incorrect", label: "Incorrect Information", icon: HelpCircle },
  { value: "other", label: "Other", icon: MessageSquareWarning },
];

export default function ReportPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = use(params);
  const router = useRouter();
  const [selectedReason, setSelectedReason] = useState("");
  const [description, setDescription] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedReason) {
      toast.error("Please select a reason for reporting");
      return;
    }

    setIsSubmitting(true);
    try {
      // API call would go here
      // await api.reportListing(id, { reason: selectedReason, description });
      await new Promise((resolve) => setTimeout(resolve, 1000)); // Simulate API
      setIsSubmitted(true);
      toast.success("Report submitted successfully");
    } catch (error) {
      console.error("Report error:", error);
      toast.error("Failed to submit report. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isSubmitted) {
    return (
      <div className="min-h-screen bg-muted/30 pb-20">
        <div className="bg-background border-b">
          <div className="container py-3 flex items-center gap-2 text-sm text-muted-foreground">
            <Link href="/" className="hover:text-primary transition-colors">
              Home
            </Link>
            <ChevronRight className="h-4 w-4" />
            <Link
              href={`/used-bike/${id}`}
              className="hover:text-primary transition-colors"
            >
              Listing
            </Link>
            <ChevronRight className="h-4 w-4" />
            <span className="text-foreground font-medium">Report</span>
          </div>
        </div>

        <div className="container py-16 max-w-lg">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.4 }}
          >
            <Card className="border-none shadow-xl text-center">
              <CardContent className="p-10 space-y-6">
                <div className="mx-auto w-16 h-16 bg-green-100 rounded-full flex items-center justify-center">
                  <CheckCircle2 className="h-8 w-8 text-green-600" />
                </div>
                <div className="space-y-2">
                  <h2 className="text-2xl font-bold">Report Submitted</h2>
                  <p className="text-muted-foreground">
                    Thank you for helping us keep MrBikeBD safe. We&apos;ll
                    review your report and take appropriate action.
                  </p>
                </div>
                <Button
                  className="w-full h-12 text-lg font-semibold"
                  onClick={() => router.push(`/used-bike/${id}`)}
                >
                  Back to Listing
                </Button>
              </CardContent>
            </Card>
          </motion.div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-muted/30 pb-20">
      {/* Breadcrumb */}
      <div className="bg-background border-b">
        <div className="container py-3 flex items-center gap-2 text-sm text-muted-foreground">
          <Link href="/" className="hover:text-primary transition-colors">
            Home
          </Link>
          <ChevronRight className="h-4 w-4" />
          <Link
            href={`/used-bike/${id}`}
            className="hover:text-primary transition-colors"
          >
            Listing
          </Link>
          <ChevronRight className="h-4 w-4" />
          <span className="text-foreground font-medium">Report</span>
        </div>
      </div>

      <div className="container py-8 max-w-lg">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4 }}
        >
          <div className="space-y-2 mb-8">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-destructive/10 rounded-xl">
                <Flag className="h-6 w-6 text-destructive" />
              </div>
              <h1 className="text-2xl font-bold">Report Listing</h1>
            </div>
            <p className="text-muted-foreground">
              Help us maintain a trustworthy marketplace. Please tell us
              what&apos;s wrong with this listing.
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Reason Selection */}
            <div className="space-y-3">
              <Label className="text-base font-semibold">
                Reason for Reporting
              </Label>
              <div className="grid gap-3">
                {REPORT_REASONS.map((reason) => (
                  <button
                    key={reason.value}
                    type="button"
                    onClick={() => setSelectedReason(reason.value)}
                    className={`flex items-center gap-4 p-4 rounded-xl border-2 text-left transition-all ${
                      selectedReason === reason.value
                        ? "border-primary bg-primary/5 shadow-sm"
                        : "border-muted bg-background hover:border-muted-foreground/20 hover:bg-muted/50"
                    }`}
                  >
                    <div
                      className={`p-2 rounded-lg ${
                        selectedReason === reason.value
                          ? "bg-primary/10"
                          : "bg-muted"
                      }`}
                    >
                      <reason.icon
                        className={`h-5 w-5 ${
                          selectedReason === reason.value
                            ? "text-primary"
                            : "text-muted-foreground"
                        }`}
                      />
                    </div>
                    <span
                      className={`font-medium ${
                        selectedReason === reason.value
                          ? "text-foreground"
                          : "text-muted-foreground"
                      }`}
                    >
                      {reason.label}
                    </span>
                    <div
                      className={`ml-auto w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                        selectedReason === reason.value
                          ? "border-primary bg-primary"
                          : "border-muted-foreground/30"
                      }`}
                    >
                      {selectedReason === reason.value && (
                        <div className="w-2 h-2 rounded-full bg-white" />
                      )}
                    </div>
                  </button>
                ))}
              </div>
            </div>

            {/* Description */}
            <div className="space-y-2">
              <Label htmlFor="description" className="text-base font-semibold">
                Additional Details{" "}
                <span className="text-muted-foreground font-normal">
                  (optional)
                </span>
              </Label>
              <Textarea
                id="description"
                placeholder="Provide any additional information that might help us investigate this report..."
                className="min-h-[120px] resize-none"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
              />
            </div>

            {/* Actions */}
            <div className="flex gap-3 pt-2">
              <Button
                type="button"
                variant="outline"
                className="flex-1 h-12"
                onClick={() => router.back()}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                className="flex-1 h-12 bg-destructive hover:bg-destructive/90 text-destructive-foreground font-semibold"
                disabled={isSubmitting || !selectedReason}
              >
                {isSubmitting ? (
                  <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                ) : (
                  <Flag className="mr-2 h-5 w-5" />
                )}
                Submit Report
              </Button>
            </div>
          </form>
        </motion.div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { useForm, useWatch, SubmitHandler, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { useSession, signIn } from "next-auth/react";
import { api } from "@/lib/api-service";
import { useShop } from "@/hooks/use-shop";
import {
  Store,
  Bike,
  CheckCircle2,
  ChevronRight,
  ChevronLeft,
  Camera,
  X,
  Loader2,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Card,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { toast } from "sonner";
import { BD_CITIES, BIKE_CONDITIONS, VALIDATION } from "@/config/constants";
import { useBrands } from "@/hooks/use-bikes";
import { compressImage } from "@/lib/image-utils";

// --- Schema ---
const formSchema = z.object({
  brand: z.string().min(1, "Brand is required"),
  customBrandInput: z.string().optional(),
  model: z.string().min(2, "Model is required"),
  year: z.coerce
    .number()
    .min(2000, "Year must be 2000 or later")
    .max(new Date().getFullYear(), "Year cannot be in the future"),
  kmDriven: z.coerce.number().min(0, "KM driven cannot be negative"),
  price: z.coerce
    .number()
    .min(
      VALIDATION.price.min,
      `Price must be at least ৳${VALIDATION.price.min}`,
    ),
  condition: z.enum(["excellent", "good", "fair", "need_work"] as const),
  description: z
    .string()
    .min(20, "Description must be at least 20 characters")
    .max(2000, "Description too long"),
  location: z.string().min(1, "Location is required"),
  accidentHistory: z.boolean().default(false),
  contactNumber: z.string().min(11, "Valid contact number is required"),
  whatsappNumber: z.string().optional(),
  engineCC: z.coerce.number().min(50, "CC must be at least 50").max(2000, "Invalid CC"),
  hasOriginalPapers: z.boolean().default(true),
  registrationYear: z.coerce.number().optional(),
  registrationType: z.string().optional(),
  engineCondition: z.string().min(3, "Required"),
  bodyCondition: z.string().min(3, "Required"),
  modifications: z.string().optional(),
  ownershipCount: z.coerce.number().min(1, "Required"),
  shopId: z.string().optional(),
});

type FormData = z.infer<typeof formSchema>;

const STEPS = ["Login", "Bike Details", "Upload Photos", "Review"];

export function SellBikeWizard() {
  const router = useRouter();
  const { data: session, status } = useSession();
  const { data: brands } = useBrands();
  const { shop } = useShop();
  const [currentStep, setCurrentStep] = useState(1);
  const [images, setImages] = useState<string[]>([]); // Preview URLs
  const [imageFiles, setImageFiles] = useState<File[]>([]); // Actual files
  const imagesRef = useRef<string[]>([]);

  // Auto-advance if logged in and verified
  useEffect(() => {
    if (status === "authenticated" && currentStep === 1) {
      setCurrentStep(2);
    }
  }, [status, session, currentStep]);

  // Update ref whenever images change
  useEffect(() => {
    imagesRef.current = images;
  }, [images]);

  // Cleanup URLs on component unmount
  useEffect(() => {
    return () => {
      imagesRef.current.forEach((url) => {
        URL.revokeObjectURL(url);
      });
    };
  }, []);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const onSubmit: SubmitHandler<FormData> = async (_data) => {
    if (isSubmitting) return;
    if (!session) {
      toast.error("You must be logged in to post an ad");
      return;
    }

    setIsSubmitting(true);
    const toastId = toast.loading("Processing your listing...");

    try {
      const formData = new FormData();
      
      const isOther = _data.brand === "other";
      const finalBrand = isOther ? (_data.customBrandInput || "Other") : _data.brand;

      // Explicitly map fields to match backend expectations
      formData.append("title", `${finalBrand} ${_data.model} ${_data.year}`);
      formData.append("price", _data.price.toString());
      formData.append("mileage", _data.kmDriven.toString());
      formData.append("manufacturing_year", _data.year.toString());
      formData.append("condition", _data.condition);
      formData.append("description", _data.description);
      formData.append("location", _data.location);
      formData.append("location_city", _data.location); // Ensure city-based URL works
      formData.append("custom_brand", finalBrand);
      formData.append("custom_model", _data.model);
      formData.append("contact_number", _data.contactNumber);
      
      if (_data.whatsappNumber) {
        formData.append("whatsapp_number", _data.whatsappNumber);
      }

      formData.append("engine_cc", _data.engineCC.toString());
      formData.append("has_original_papers", _data.hasOriginalPapers ? "true" : "false");
      formData.append("registration_year", (_data.registrationYear || _data.year).toString());
      if (_data.registrationType) {
        formData.append("registration_type", _data.registrationType);
      }
      formData.append("engine_condition", _data.engineCondition);
      formData.append("body_condition", _data.bodyCondition);
      formData.append("modifications", _data.modifications || "None");
      formData.append("ownership_count", _data.ownershipCount.toString());
      
      if (_data.shopId) {
        formData.append("shop", _data.shopId);
      }

      // Compress and append images
      toast.loading(`Compressing ${imageFiles.length} images...`, { id: toastId });
      
      for (let i = 0; i < imageFiles.length; i++) {
        const file = imageFiles[i];
        try {
          // Use high quality for 'premium' feel and Full HD resolution
          const compressedBlob = await compressImage(file, { 
            quality: 0.95, 
            maxWidth: 1920,
            maxHeight: 1920 
          });
          const compressedFile = new File([compressedBlob], file.name, { type: "image/jpeg" });
          formData.append("uploaded_images", compressedFile);
        } catch (err) {
          console.error("Compression failed for image", i, err);
          formData.append("uploaded_images", file); // Fallback to original
        }
      }

      toast.loading("Uploading to server...", { id: toastId });
      const response = await api.createUsedBike(formData);
      
      if (!response.success) {
        throw new Error(response.error?.message || "Failed to create listing");
      }
 
      toast.success("Ad posted successfully! It is under review.", { id: toastId });
      router.push("/used-bikes");
    } catch (error: any) {
      console.error("Failed to post ad:", error);
      toast.error(error.message || "Failed to post ad. Please try again.", { id: toastId });
    } finally {
      setIsSubmitting(false);
    }
  };

  const form = useForm<FormData>({
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    resolver: zodResolver(formSchema) as any,
    defaultValues: {
      brand: "",
      model: "",
      year: new Date().getFullYear(),
      kmDriven: 0,
      price: 0,
      condition: "good",
      accidentHistory: false,
      description: "",
      location: "",
      contactNumber: "",
      whatsappNumber: "",
      engineCC: 150,
      hasOriginalPapers: true,
      registrationYear: new Date().getFullYear(),
      registrationType: "Digital Plate",
      engineCondition: "Solid Engine",
      bodyCondition: "No Scratches",
      modifications: "None",
      ownershipCount: 1,
      shopId: "",
    },
  });

  // Auto-set shopId if shop exists
  useEffect(() => {
    if (shop?.id) {
       form.setValue("shopId", shop.id.toString());
    }
  }, [shop, form]);

  const watchedValues = useWatch({ control: form.control }); // Watch all values for review step

  // --- Actions ---

  const handleLogin = () => {
    if (status === "unauthenticated") {
      signIn();
    } else if (status === "authenticated") {
      setCurrentStep(2);
    }
  };

  const handleNext = async () => {
    if (currentStep === 2) {
      const valid = await form.trigger();
      if (!valid) {
        // Find first error and scroll to it
        const errors = form.formState.errors;
        const firstErrorKey = Object.keys(errors)[0] as keyof typeof errors;
        if (firstErrorKey) {
          const element = document.getElementById(firstErrorKey);
          if (element) {
            element.scrollIntoView({ behavior: "smooth", block: "center" });
          } else {
            // Fallback for custom components that might not have ID on the root
            const fieldElement = document.querySelector(
              `[name="${firstErrorKey}"]`,
            );
            fieldElement?.scrollIntoView({
              behavior: "smooth",
              block: "center",
            });
          }
        }
        return;
      }
    }
    if (currentStep === 3 && images.length === 0) {
      toast.error("Please upload at least one photo");
      return;
    }

    setCurrentStep((prev) => Math.min(prev + 1, 4));
  };

  const handleBack = () => {
    setCurrentStep((prev) => Math.max(prev - 1, 1));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    // Check available slots first
    const availableSlots = 5 - images.length;
    if (availableSlots <= 0) {
      toast.error("Maximum 5 images allowed");
      return;
    }

    // Only convert up to available slots to URLs
    const filesToConvert = Array.from(files).slice(0, availableSlots);
    const newImages = filesToConvert.map((file) => URL.createObjectURL(file));

    if (files.length > availableSlots) {
      toast.warning(
        `Only ${availableSlots} image(s) can be added. ${files.length - availableSlots} file(s) were not added.`,
      );
    }

    setImages([...images, ...newImages]);
    setImageFiles([...imageFiles, ...filesToConvert]);
  };

  const removeImage = (index: number) => {
    URL.revokeObjectURL(images[index]);
    setImages(images.filter((_, i) => i !== index));
    setImageFiles(imageFiles.filter((_, i) => i !== index));
  };

  // Pre-fill contact number if available
  useEffect(() => {
    if (session?.user?.phone && !form.getValues("contactNumber")) {
      form.setValue("contactNumber", session.user.phone);
    }
  }, [session, form]);


  return (
    <div className="max-w-3xl mx-auto py-8">
      <div className="mb-8 text-center space-y-2">
        <h1 className="text-3xl font-bold tracking-tight">
          Sell Your Bike on MrBikeBD
        </h1>
        <p className="text-muted-foreground">Post your ad in 3 simple steps</p>
      </div>

      {/* Progress Bar */}
      <div className="mb-8">
        <div className="grid grid-cols-4 gap-2 mb-2">
          {STEPS.map((stepName, i) => (
            <div
              key={i}
              className={`h-1.5 rounded-full ${i + 1 <= currentStep ? "bg-primary" : "bg-muted"}`}
            />
          ))}
        </div>
        <div className="flex justify-between text-xs font-medium text-muted-foreground uppercase tracking-wider">
          <span>Login</span>
          <span className="text-center">Details</span>
          <span className="text-center">Photos</span>
          <span className="text-right">Finish</span>
        </div>
      </div>

      <Card className="border-2">
        <CardHeader>
          <CardTitle>{STEPS[currentStep - 1]}</CardTitle>
        </CardHeader>
        <CardContent className="min-h-[400px]">
          {currentStep === 1 && (
            <div className="text-center py-10 space-y-6">
              <div className="bg-primary/10 w-20 h-20 rounded-full flex items-center justify-center mx-auto">
                <Bike className="h-10 w-10 text-primary" />
              </div>
              <div>
                <h2 className="text-2xl font-bold mb-2">
                  Login to Sell Your Bike on MrBikeBD
                </h2>
                <p className="text-muted-foreground max-w-md mx-auto">
                  You need to be logged in to post an ad. This helps us verify
                  sellers and keep the marketplace safe.
                </p>
              </div>

              {status === "unauthenticated" ? (
                <div className="flex flex-col gap-3 max-w-xs mx-auto">
                  <Button onClick={handleLogin} className="w-full" size="lg">
                    Continue with Google
                  </Button>
                  <div className="relative">
                    <div className="absolute inset-0 flex items-center">
                      <span className="w-full border-t" />
                    </div>
                    <div className="relative flex justify-center text-xs uppercase">
                      <span className="bg-background px-2 text-muted-foreground">
                        Or
                      </span>
                    </div>
                  </div>
                  <Button variant="outline" onClick={handleLogin}>
                    Continue with Phone
                  </Button>
                </div>
              ) : null}
            </div>
          )}

          {currentStep === 2 && (
            <div className="space-y-6">
              <div className="grid md:grid-cols-2 gap-6">
                {/* Brand */}
                <div className="space-y-2">
                  <Label htmlFor="brand">Brand</Label>
                  <Controller
                    name="brand"
                    control={form.control}
                    render={({ field }) => (
                      <Select
                        onValueChange={field.onChange}
                        defaultValue={field.value}
                      >
                        <SelectTrigger id="brand">
                          <SelectValue placeholder="Select Brand" />
                        </SelectTrigger>
                        <SelectContent>
                          {brands?.map(
                            (b: {
                              id: string | number;
                              slug: string;
                              name: string;
                            }) => (
                              <SelectItem key={b.id} value={b.slug}>
                                {b.name}
                              </SelectItem>
                            ),
                          )}
                          <SelectItem value="yamaha">Yamaha</SelectItem>
                          <SelectItem value="gpx-demon">GPX Demon</SelectItem>
                          <SelectItem value="other">Other</SelectItem>
                        </SelectContent>
                      </Select>
                    )}
                  />
                  {form.formState.errors.brand && (
                    <p className="text-red-500 text-sm">
                      {form.formState.errors.brand.message}
                    </p>
                  )}
                </div>

                {/* Custom Brand Input (Conditional) */}
                {watchedValues.brand === "other" && (
                  <div className="space-y-2">
                    <Label htmlFor="customBrandInput">Custom Brand Name</Label>
                    <Input
                      id="customBrandInput"
                      placeholder="Enter brand name (e.g. Gpx Demon, Lifan)"
                      {...form.register("customBrandInput")}
                    />
                    {form.formState.errors.customBrandInput && (
                      <p className="text-red-500 text-sm">
                        {form.formState.errors.customBrandInput.message}
                      </p>
                    )}
                  </div>
                )}

                {/* Model */}
                <div className="space-y-2">
                  <Label htmlFor="model">Model</Label>
                  <Input
                    id="model"
                    placeholder="e.g. R15 V3, Gixxer SF"
                    {...form.register("model")}
                  />
                  {form.formState.errors.model && (
                    <p className="text-red-500 text-sm">
                      {form.formState.errors.model.message}
                    </p>
                  )}
                </div>

                {/* Year */}
                <div className="space-y-2">
                  <Label htmlFor="year">Year of Manufacture</Label>
                  <Input
                    id="year"
                    type="number"
                    {...form.register("year")}
                    onFocus={(e) => e.target.select()}
                  />
                  {form.formState.errors.year && (
                    <p className="text-red-500 text-sm">
                      {form.formState.errors.year.message}
                    </p>
                  )}
                </div>

                {/* KM Driven */}
                <div className="space-y-2">
                  <Label htmlFor="kmDriven">Kilometers Driven</Label>
                  <div className="relative">
                    <Input
                      id="kmDriven"
                      type="number"
                      {...form.register("kmDriven")}
                      className="pr-10"
                      onFocus={(e) => {
                        if (e.target.value === "0") {
                          form.setValue("kmDriven", "" as any);
                        }
                        e.target.select();
                      }}
                    />
                    <span className="absolute right-3 top-2.5 text-muted-foreground text-sm">
                      km
                    </span>
                  </div>
                  {form.formState.errors.kmDriven && (
                    <p className="text-red-500 text-sm">
                      {form.formState.errors.kmDriven.message}
                    </p>
                  )}
                </div>

                {/* Price */}
                <div className="space-y-2">
                  <Label htmlFor="price">Expected Price (Tk)</Label>
                  <div className="relative">
                    <span className="absolute left-3 top-2.5 text-muted-foreground font-bold">
                      ৳
                    </span>
                    <Input
                      id="price"
                      type="number"
                      {...form.register("price")}
                      className="pl-8"
                      onFocus={(e) => {
                        if (e.target.value === "0") {
                          form.setValue("price", "" as any);
                        }
                        e.target.select();
                      }}
                    />
                  </div>
                  {form.formState.errors.price && (
                    <p className="text-red-500 text-sm">
                      {form.formState.errors.price.message}
                    </p>
                  )}
                </div>

                {/* Condition */}
                <div className="space-y-2">
                  <Label htmlFor="condition">Condition</Label>
                  <Controller
                    name="condition"
                    control={form.control}
                    render={({ field }) => (
                      <Select
                        onValueChange={field.onChange}
                        defaultValue={field.value}
                      >
                        <SelectTrigger id="condition">
                          <SelectValue placeholder="Select Condition" />
                        </SelectTrigger>
                        <SelectContent>
                          {BIKE_CONDITIONS.map((c) => (
                            <SelectItem key={c.value} value={c.value}>
                              {c.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  />
                </div>

                {/* Location */}
                <div className="space-y-2">
                  <Label htmlFor="location">Location</Label>
                  <Controller
                    name="location"
                    control={form.control}
                    render={({ field }) => (
                      <Select
                        onValueChange={field.onChange}
                        defaultValue={field.value}
                      >
                        <SelectTrigger id="location">
                          <SelectValue placeholder="Select District/City" />
                        </SelectTrigger>
                        <SelectContent>
                          {BD_CITIES.map((city) => (
                            <SelectItem key={city} value={city}>
                              {city}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  />
                  {form.formState.errors.location && (
                    <p className="text-red-500 text-sm">
                      {form.formState.errors.location.message}
                    </p>
                  )}
                </div>
              </div>

              {/* Description */}
              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  placeholder="Tell buyers about your bike (mods, service history, scratches, etc.)"
                  className="h-32"
                  {...form.register("description")}
                />
                {form.formState.errors.description && (
                  <p className="text-red-500 text-sm">
                    {form.formState.errors.description.message}
                  </p>
                )}
              </div>

              <div className="flex items-center space-x-2 border p-4 rounded-lg bg-muted/20">
                <Checkbox
                  id="accidentHistory"
                  checked={watchedValues.accidentHistory}
                  onCheckedChange={(checked) =>
                    form.setValue("accidentHistory", checked as boolean)
                  }
                />
                <div className="grid gap-1.5 leading-none">
                  <Label
                    htmlFor="accidentHistory"
                    className="font-medium cursor-pointer"
                  >
                    This bike has been in major accidents
                  </Label>
                  <p className="text-sm text-muted-foreground">
                    Honesty helps build trust with buyers.
                  </p>
                </div>
              </div>

              <div className="pt-4 border-t space-y-6">
                <h3 className="text-lg font-semibold">Technical Specifications</h3>
                <div className="grid md:grid-cols-2 gap-6">
                  {/* Engine CC */}
                  <div className="space-y-2">
                    <Label htmlFor="engineCC">Engine CC</Label>
                    <Input
                      id="engineCC"
                      type="number"
                      placeholder="e.g. 150, 160"
                      {...form.register("engineCC")}
                    />
                    {form.formState.errors.engineCC && (
                      <p className="text-red-500 text-sm">{form.formState.errors.engineCC.message}</p>
                    )}
                  </div>

                  {/* Ownership Count */}
                  <div className="space-y-2">
                    <Label htmlFor="ownershipCount">Ownership</Label>
                    <Controller
                      name="ownershipCount"
                      control={form.control}
                      render={({ field }) => (
                        <Select onValueChange={field.onChange} defaultValue={field.value.toString()}>
                          <SelectTrigger id="ownershipCount">
                            <SelectValue placeholder="Select Ownership" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="1">1st Owner</SelectItem>
                            <SelectItem value="2">2nd Owner</SelectItem>
                            <SelectItem value="3">3rd Owner</SelectItem>
                            <SelectItem value="4">4th Owner+</SelectItem>
                          </SelectContent>
                        </Select>
                      )}
                    />
                  </div>

                  {/* Registration Year */}
                  <div className="space-y-2">
                    <Label htmlFor="registrationYear">Registration Year</Label>
                    <Input
                      id="registrationYear"
                      type="number"
                      placeholder="e.g. 2024"
                      {...form.register("registrationYear")}
                    />
                  </div>

                  {/* Registration Type */}
                  <div className="space-y-2">
                    <Label htmlFor="registrationType">Registration Type</Label>
                    <Controller
                      name="registrationType"
                      control={form.control}
                      render={({ field }) => (
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <SelectTrigger id="registrationType">
                            <SelectValue placeholder="Select Type" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="Digital Plate">Digital Number Plate</SelectItem>
                            <SelectItem value="Analog Plate">Analog Number Plate</SelectItem>
                            <SelectItem value="Apply Done">Registration Applied (Done)</SelectItem>
                            <SelectItem value="Not Registered">Not Registered</SelectItem>
                          </SelectContent>
                        </Select>
                      )}
                    />
                  </div>

                  {/* Papers Status */}
                  <div className="flex items-center space-x-2 border p-4 rounded-lg bg-muted/20 h-[58px] mt-auto">
                    <Checkbox
                      id="hasOriginalPapers"
                      checked={watchedValues.hasOriginalPapers}
                      onCheckedChange={(checked) =>
                        form.setValue("hasOriginalPapers", checked as boolean)
                      }
                    />
                    <Label htmlFor="hasOriginalPapers" className="font-medium cursor-pointer">
                      I have original papers
                    </Label>
                  </div>

                  {/* Engine Condition */}
                  <div className="space-y-2">
                    <Label htmlFor="engineCondition">Engine Condition</Label>
                    <Input
                      id="engineCondition"
                      placeholder="e.g. Fresh, Never Opened"
                      {...form.register("engineCondition")}
                    />
                  </div>

                  {/* Body Condition */}
                  <div className="space-y-2">
                    <Label htmlFor="bodyCondition">Body Condition</Label>
                    <Input
                      id="bodyCondition"
                      placeholder="e.g. Neat & Clean"
                      {...form.register("bodyCondition")}
                    />
                  </div>
                </div>

                {/* Modifications */}
                <div className="space-y-2">
                  <Label htmlFor="modifications">Modifications (Optional)</Label>
                  <Input
                    id="modifications"
                    placeholder="e.g. Exhaust, Handlebar, etc."
                    {...form.register("modifications")}
                  />
                </div>
              </div>

              {/* Contact Number */}
              <div className="space-y-2">
                <Label htmlFor="contactNumber">
                  Contact Number (For Buyers)
                </Label>
                <Input
                  id="contactNumber"
                  placeholder="e.g. 01XXXXXXXXX"
                  {...form.register("contactNumber")}
                />
                <p className="text-xs text-muted-foreground">
                  Buyers will use this number to contact you.
                </p>
                {form.formState.errors.contactNumber && (
                  <p className="text-red-500 text-sm">
                    {form.formState.errors.contactNumber.message}
                  </p>
                )}
              </div>

              {/* Whatsapp Number */}
              <div className="space-y-2">
                <Label htmlFor="whatsappNumber">
                  Whatsapp Number (Optional)
                </Label>
                <Input
                  id="whatsappNumber"
                  placeholder="e.g. 01XXXXXXXXX"
                  {...form.register("whatsappNumber")}
                />
                <p className="text-xs text-muted-foreground">
                  Provide your Whatsapp number if different from your contact number.
                </p>
              </div>

              {/* Shop Association */}
              {shop && (
                <div className="flex items-center space-x-2 border-2 border-orange-100 p-4 rounded-xl bg-orange-50/50">
                  <Checkbox
