"use client";

import { useState, useMemo } from "react";
import { useRouter } from "next/navigation";
import { useBikes } from "@/hooks/use-bikes";
import { Bike } from "@/types";
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Loader2 } from "lucide-react";

export function SearchDialog({
  open,
  onOpenChange,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const [search, setSearch] = useState("");
  const router = useRouter();

  // Fetch bikes based on search query
  const { data, isLoading } = useBikes({
    search: search.length >= 2 ? search : undefined,
    limit: 10,
  });

  const bikes = data?.bikes || [];

  const handleSelect = (slug: string) => {
    onOpenChange(false);
    router.push(`/bike/${slug}`);
  };

  return (
    <CommandDialog open={open} onOpenChange={onOpenChange}>
      <CommandInput
        placeholder="Search bikes or brands..."
        value={search}
        onValueChange={setSearch}
      />
      <CommandList>
        {isLoading && (
          <div className="flex items-center justify-center p-4">
            <Loader2 className="h-4 w-4 animate-spin mr-2" />
            <span className="text-sm text-muted-foreground">Searching...</span>
          </div>
        )}
        {!isLoading && search.length >= 2 && bikes.length === 0 && (
          <CommandEmpty>No results found for &quot;{search}&quot;.</CommandEmpty>
        )}
        {!isLoading && search.length < 2 && (
          <CommandEmpty>Type at least 2 characters to search.</CommandEmpty>
        )}

        {bikes.length > 0 && (
          <CommandGroup heading="Bikes Found">
            {bikes.map((bike: Bike) => (
              <CommandItem
                key={bike.id}
                onSelect={() => handleSelect(bike.slug)}
                className="cursor-pointer"
              >
                <div className="flex flex-col">
                  <span className="font-medium">{bike.brand_name} {bike.name}</span>
                  <span className="text-xs text-muted-foreground">{bike.category}</span>
                </div>
              </CommandItem>
            ))}
          </CommandGroup>
        )}
      </CommandList>
    </CommandDialog>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useAuthStore } from "@/store";
import { User } from "@/types";
import { api } from "@/lib/api-service";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { PasswordInput } from "@/components/ui/password-input";
import { Switch } from "@/components/ui/switch";
import { Loader2 } from "lucide-react";
import { toast } from "sonner";

export function AccountManagement() {
  const { user, login } = useAuthStore();
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    location: "",
  });

  // Password Change State
  const [passwordData, setPasswordData] = useState({
    currentPassword: "",
    newPassword: "",
    confirmPassword: "",
  });

  useEffect(() => {
    if (user) {
      setFormData({
        name: user.name || "",
        email: user.email || "",
        phone: user.phone || "",
        location: user.location || "",
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.name, user?.email, user?.phone, user?.location]);

  const handleSaveProfile = async () => {
    setIsSaving(true);
    try {
      const response = await api.updateProfile({
        first_name: formData.name.split(" ")[0] || "",
        last_name: formData.name.split(" ").slice(1).join(" ") || "",
        phone: formData.phone,
        location: formData.location,
      });

      if (response.success) {
        const updatedUser = response.data as any;
        if (user) {
          login({
            ...user,
            id: updatedUser.id ? updatedUser.id.toString() : user.id,
            name: `${updatedUser.first_name || ""} ${updatedUser.last_name || ""}`.trim() || updatedUser.username || user.name,
            phone: updatedUser.phone || user.phone,
            location: updatedUser.location || user.location,
            image: updatedUser.profile_image || user.image,
            isEmailVerified: updatedUser.is_email_verified ?? user.isEmailVerified,
          } as User);
        }
        toast.success("Profile updated successfully");
      } else {
        toast.error(response.error?.message || "Failed to update profile");
      }
    } catch (error) {
      toast.error("An unexpected error occurred");
    } finally {
      setIsSaving(false);
    }
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordData.newPassword !== passwordData.confirmPassword) {
      toast.error("New passwords do not match");
      return;
    }

    setIsSaving(true);
    // Simulate API call
    await new Promise((resolve) => setTimeout(resolve, 1500));

    setIsSaving(false);
    setPasswordData({
      currentPassword: "",
      newPassword: "",
      confirmPassword: "",
    });
    toast.success("Password changed successfully");
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Profile Details</CardTitle>
          <CardDescription>
            Manage your public profile and contact info.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-2">
            <Label htmlFor="name">Full Name</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
            />
          </div>
          <div className="grid gap-2">
            <div className="flex items-center gap-2">
              <Input
                id="email"
                value={formData.email}
                disabled
                className="bg-muted flex-1"
              />
            </div>
            <p className="text-[0.8rem] text-muted-foreground">
              Email cannot be changed as it is linked to your account.
            </p>
          </div>
          <div className="grid gap-2">
            <Label htmlFor="phone">Phone Number</Label>
            <Input
              id="phone"
              placeholder="+880 1XXX XXXXXX"
              value={formData.phone}
              onChange={(e) =>
                setFormData({ ...formData, phone: e.target.value })
              }
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="location">City / District</Label>
            <Input
              id="location"
              placeholder="e.g. Dhaka, Chittagong"
              value={formData.location}
              onChange={(e) =>
                setFormData({ ...formData, location: e.target.value })
              }
            />
          </div>
        </CardContent>
        <CardFooter>
          <Button onClick={handleSaveProfile} disabled={isSaving}>
            {isSaving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {isSaving ? "Saving..." : "Save Changes"}
          </Button>
        </CardFooter>
      </Card>



      <Card>
        <CardHeader>
          <CardTitle>Security</CardTitle>
          <CardDescription>
            Update your password and security settings.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleChangePassword} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="currentPassword">Current Password</Label>
              <PasswordInput
                id="currentPassword"
                value={passwordData.currentPassword}
                onChange={(e) =>
                  setPasswordData({
                    ...passwordData,
                    currentPassword: e.target.value,
                  })
                }
                required
              />
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="newPassword">New Password</Label>
                <PasswordInput
                  id="newPassword"
                  value={passwordData.newPassword}
                  onChange={(e) =>
                    setPasswordData({
                      ...passwordData,
                      newPassword: e.target.value,
                    })
                  }
                  required
                  minLength={8}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="confirmNewPassword">Confirm New Password</Label>
                <PasswordInput
                  id="confirmNewPassword"
                  value={passwordData.confirmPassword}
                  onChange={(e) =>
                    setPasswordData({
                      ...passwordData,
                      confirmPassword: e.target.value,
                    })
                  }
                  required
                  minLength={8}
                />
              </div>
            </div>
            <div className="flex justify-end pt-2">
              <Button type="submit" variant="outline" disabled={isSaving}>
                Update Password
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Notifications</CardTitle>
          <CardDescription>Manage how we communicate with you.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between space-x-2">
            <Label htmlFor="marketing" className="flex flex-col space-y-1">
              <span>Marketing Emails</span>
              <span className="font-normal text-xs text-muted-foreground">
                Receive emails about new products, features, and more.
              </span>
            </Label>
            <Switch id="marketing" defaultChecked />
          </div>
          <div className="flex items-center justify-between space-x-2">
            <Label htmlFor="security" className="flex flex-col space-y-1">
              <span>Security Emails</span>
              <span className="font-normal text-xs text-muted-foreground">
                Receive emails about your account security.
              </span>
            </Label>
            <Switch id="security" defaultChecked disabled />
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import React from "react";
import Link from "next/link";
import Image from "next/image";
import { motion } from "framer-motion";
import { Sparkles, Bike, MapPin, Gauge } from "lucide-react";
import { formatPrice } from "@/lib/utils";
import { useEmotionalRecommendations } from "@/hooks/use-recommendations";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";

interface EmotionalTriggersProps {
  slug: string;
  bikeName: string;
}

export function EmotionalTriggers({ slug, bikeName }: EmotionalTriggersProps) {
  const { data: recommendations, isLoading, error } = useEmotionalRecommendations(slug);

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-8 w-64" />
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <Skeleton key={i} className="h-64 w-full rounded-xl" />
          ))}
        </div>
      </div>
    );
  }

  if (error || !recommendations || recommendations.length === 0) {
    return null;
  }

  return (
    <section className="py-8 border-t">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <Sparkles className="h-5 w-5 text-primary animate-pulse" />
            <span className="text-primary font-bold tracking-tight uppercase text-sm">
              Emotional Trigger
            </span>
          </div>
          <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-foreground to-foreground/70">
            For the same price as the {bikeName}, you could own these premium legends:
          </h2>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {recommendations.map((listing, index) => (
          <motion.div
            key={listing.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.1 }}
            className="group relative bg-card border rounded-xl overflow-hidden hover:border-primary/50 hover:shadow-lg transition-all duration-300"
          >
            <Link href={`/used-bike/${listing.slug}`} className="block">
              {/* Image Container */}
              <div className="aspect-[4/3] relative overflow-hidden bg-muted">
                <Image
                  src={listing.thumbnailUrl || "/placeholder-bike.png"}
                  alt={listing.bikeName}
                  fill
                  className="object-cover transition-transform duration-500 group-hover:scale-110"
                />

                {/* Condition Badge */}
                <div className="absolute top-3 left-3">
                  <Badge variant="secondary" className="bg-white/90 backdrop-blur-sm text-[10px] font-bold uppercase py-0.5">
                    {listing.condition}
                  </Badge>
                </div>

                {/* Price Overaly */}
                <div className="absolute bottom-0 left-0 right-0 p-3 bg-gradient-to-t from-black/80 to-transparent">
                   <div className="text-white font-bold text-lg">
                    {formatPrice(listing.price)}
                   </div>
                </div>
              </div>

              {/* Content */}
              <div className="p-4">
                <h3 className="font-bold text-sm truncate mb-2 group-hover:text-primary transition-colors">
                  {listing.bikeName}
                </h3>

                <div className="grid grid-cols-2 gap-2 text-xs text-muted-foreground">
                  <div className="flex items-center gap-1">
                    <Gauge className="h-3 w-3" />
                    <span>{listing.kmDriven || "N/A"} km</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <MapPin className="h-3 w-3" />
                    <span className="truncate">{listing.location?.city || "BD"}</span>
                  </div>
                </div>

                <div className="mt-4 pt-3 border-t flex items-center justify-between">
                   <span className="text-[10px] font-bold text-primary uppercase flex items-center gap-1">
                     <Sparkles className="h-3 w-3" />
                     Premium Match
                   </span>
                   <span className="text-[10px] text-muted-foreground">
                     {listing.year}
                   </span>
                </div>
              </div>
            </Link>
          </motion.div>
        ))}
      </div>
    </section>
  );
}

